        "tbp_sec1_title": "ÜÇ CİSİM PROBLEMİ (THREE-BODY PROBLEM)",
        "tbp_sec1_desc": "İki gök cisminin, ideal koşullarda, hareketi kapalı biçimde analitik olarak çözülebilir. Ancak üçüncü bir kütle eklendiğinde genel durumda kapalı biçimli bir çözüm yoktur; hareket sayısal yöntemlerle hesaplanır. Sistem deterministiktir ve bazı başlangıç koşullarında kaotik davranabilir; başlangıç konumu veya hızındaki çok küçük farklar, özellikle uzun zamanlarda, belirgin biçimde farklı yörüngelere yol açabilir.",
