        "tbp_sec2_desc": "Kaotik davranış, başlangıç koşullarına duyarlılık demektir; her kaotik sistem zorunlu olarak kararsız değildir. Üç cisim birbirine yaklaştığında hızlar artabilir ve etkileşim sonucunda cisimlerden biri bağlı olmayan bir yörüngeye geçerek <strong>uzaklaşabilir (fırlatılma)</strong>; bu her başlangıç koşulunda gerçekleşmez. <strong>\"Bariyersiz\"</strong> seçeneğinde bu olasılığı gözlemleyebilirsiniz. <strong>\"Bariyerli\"</strong> seçeneğinde ise simülasyona eklenmiş yapay, merkeze doğru bir sınırlayıcı kuvvet cisimlerin ekranda kalmasına yardımcı olur; bu, gerçek bir kütleçekim alanı değildir.",
