        "dp_card2_desc": "Ekrandaki izler üst üste binebilir. Aynı konum ve hızlara sahip tam fiziksel durum yeniden oluşursa hareket periyodik olur; ideal çift sarkaçta özel başlangıç koşullarıyla bu mümkündür. Kaotik durumda ise küçük başlangıç farkları zamanla büyür ve uzun vadeli tahmini zorlaştırır.",
        "dp_card3_title": "Deterministik Kaos",
        "dp_card3_desc": "Bu hareket tamamen kesin fizik kurallarına (yerçekimi ve Newton yasalarına) bağlıdır, rastgele değildir. Ancak kurallar o kadar lineer olmayan bir karmaşıklık sunar ki, geleceği uzun vadede hesaplamak imkansızdır.",

        // --- SİMÜLASYON SAYFASI: LORENZ ÇEKERİ ---
        "lz_page_title": "Lorenz Çekeri - Etkileşimli Kaos",
