        "lz_warming": "ISINIYOR",
        "lz_periodic": "Periyodik Rejim",
        "lz_chaotic": "Kaotik Rejim",
        "lz_extreme": "Aşırı Kaos",
        "lz_title": "Lorenz Çekeri",
        "lz_subtitle": "Kaos Teorisinin Kalbi",
        "lz_chaos_degree": "Kaos Derecesi (Rho: ρ)",
        "lz_periodic_preset": "Periyodik",
        "lz_chaotic_preset": "Kaotik",
        "lz_extreme_preset": "Aşırı Kaos",
        "lz_focus": "Kelebek Açısına Kilitlen",
        "lz_reset": "Yörüngeyi Sıfırla",
        "lz_what_title": "Nedir? (Kaos Teorisi)",
        "lz_what_desc": "1963'te meteorolog Edward Lorenz hava durumunu bilgisayarda modellerken bir şey fark etti: Başlangıç verilerindeki <strong>0.0001'lik bir yuvarlama hatası</strong> bile bir süre sonra tamamen farklı bir hava durumu tahmini üretiyordu. Bu simülasyon, o hava akımlarının matematiksel olarak 3 boyutlu uzaya dökülmüş halidir.",
        "lz_butterfly_title": "Kelebek Etkisi",
        "lz_butterfly_desc": "<strong>\"Brezilya'daki bir kelebeğin kanat çırpması, Teksas'ta bir kasırgaya neden olabilir.\"</strong> Bu, kaotik sistemlerde küçük başlangıç farklarının büyüyebilmesini anlatan bir benzetmedir; doğrudan bir nedensellik yasası değildir. Lorenz sisteminin iki kanatlı geometrisi <strong>garip çeker</strong> olarak adlandırılır. Üç boyutlu faz uzayındaki yörünge kendi kendisiyle kesişmez; iki boyutlu çizimde görülen kesişmeler izdüşümden kaynaklanabilir.",
        "lz_deterministic_title": "Deterministik Kaos",
        "lz_deterministic_desc": "Bu sistem rastgele (random) değildir! Her şey kesin matematiksel kurallara (Türevsel denklemlere) bağlıdır. Ancak kurallar o kadar hassastır ki, geleceği uzun vadede tahmin etmek imkansızdır. Düzenin içinden kaos, kaosun içinden ise (kelebek şeklinde) muazzam bir düzen doğar.",
        "lz_uses_title": "Nerede Kullanılır?",
        "lz_uses_desc": "Hava durumu tahminlerinin neden sadece birkaç gün tutarlı kalıp 10 günden sonra tamamen çuvalladığının matematiksel kanıtıdır. Ayrıca <strong>Borsa analizlerinde, kalp ritmi incelemelerinde, akışkanlar mekaniğinde (su/hava türbülansı) ve hatta şifreleme (kriptografi) teknolojilerinde</strong> doğanın bu rastgele gibi görünen ama kurallı sistemleri kullanılır.",

