        "aurora_panel_title": "Güneş & IMF B<sub>z</sub> Aurora Fiziği",
        "aurora_panel_desc": "3D Manyetik Reconnection & Uzay Hava Durumu Modeli.",
        "aurora_lbl_speed": "Güneş Rüzgarı Hızı (v)",
        "aurora_lbl_bz": "IMF B<sub>z</sub> (Kutupsallık)",
        "aurora_lbl_count": "Parçacık Yoğunluğu",
        "aurora_lbl_field": "Manyetik Alan Çizgileri",
