        "aurora_tele_reconn": "Reconnection:",
        "aurora_reconn_active": "Açık (Güney)",
        "aurora_reconn_inactive": "Kapalı (Kuzey)",
        "aurora_tele_power": "Auroral Güç İndeksi:",
        "aurora_btn_reset_cam": "Kamerayı Sıfırla",
        "aurora_legend_shock": "Bow Shock (Şok Dalgası)",
        "aurora_legend_tail": "Magnetotail Plazma Kuyruğu",
        "aurora_legend_storm": "Şiddetli Fırtına Emisyonu (Kırmızı / Pembe)",
        "aurora_info_main_title": "Aurora ve Manyetosfer Fiziği",
        "aurora_sec1_title": "1. Güneş Rüzgarı ve IMF B<sub>z</sub> Nedir?",
        "aurora_sec1_desc": "Güneş, uzaya süpersonik hızlarda yüklü plazma fırlatır. Bu plazma, Güneş'in kendi manyetik alanını da uzaya doğru sürükler. Buna <b>Gezegenlerarası Manyetik Alan (IMF)</b> denir. <b>B<sub>z</sub></b> ise bu manyetik alanın Dünya'ya ulaşan kısmının Kuzey-Güney (Z ekseni) doğrultusudur.",
        "aurora_sec2_title": "2. Manyetik Kalkan ve Şok Dalgası (Bow Shock)",
        "aurora_sec2_desc": "Dünya'nın manyetik alanı, esas olarak dış çekirdekteki iletken sıvı hareketlerinin oluşturduğu jeodinamo ile üretilir ve manyetosferi oluşturur. Bu manyetosfer yüklü güneş plazmasına karşı koruyucu bir bölge görevi görür. Güneş rüzgarı süpersonik hızla geldiğinde, Dünya'nın ön tarafında bir <b>şok dalgası (bow shock)</b> oluşur.",
        "aurora_sec3_title": "3. Neden B<sub>z</sub> Negatifken Fırtına Kopar?",
        "aurora_sec3_desc": "Güneş rüzgarındaki B<sub>z</sub> bileşeni güneye, yani negatif yönde olduğunda, Dünya'nın manyetik alanıyla uygun koşullarda manyetik yeniden bağlanma kolaylaşır. Bu süreç enerji ve parçacık aktarımını artırabilir; ancak manyetosfer tamamen ortadan kalkmaz ve plazma basitçe doğrudan içeri akmaz.",
        "aurora_sec4_title": "4. Auroralar Neden Şiddetlenir?",
        "aurora_sec4_desc": "Güneş rüzgarıyla aktarılan enerji manyetosferin arka tarafındaki <b>manyetik kuyrukta (magnetotail)</b> depolanabilir. Negatif B<sub>z</sub> genellikle enerji girişini artırır; fakat etki yalnızca B<sub>z</sub>'ye bağlı değildir. Kuyruktaki enerji boşalmaları, parçacıkları kutuplara yönlendirerek auroral ovalin genişlemesine ve auroranın parlaklaşmasına katkıda bulunabilir.",
        "aurora_sec5_title": "💡 Atmosferik Çarpışmalar ve Renkler",
        "aurora_sec5_desc": "Kutup bölgelerine yönelen enerjik parçacıklar atmosferdeki atom ve molekülleri uyarır; bu parçacıklar daha düşük enerji durumlarına dönerken ışık yayılır: <br><br>• <b>Yeşil:</b> Yaklaşık 100–150 km yükseklikte uyarılmış atomik oksijenin emisyonları baskındır.<br><br>• <b>Kırmızı:</b> Özellikle yüksek irtifadaki seyrek atomik oksijenin emisyonlarıyla ilişkilidir. Azot ve moleküler azot iyonları da mavi, mor ve kırmızımsı tonlara katkıda bulunabilir. Renkler tek başına fırtınanın gücünü kesin olarak belirlemez.",

