        "qs_info_title": " Bilimsel Açıklamalar",
        "qs_info_duality_title": "Dalga - Parçacık İkiliği",
        "qs_info_duality_desc": "Klasik fizikte ışık bir dalga gibi davranır. Ancak \"Kuantum Modu\"nda parçacıkları (foton/elektron) tek tek gönderdiğimizde bile zamanla ekranda dalga modeliyle birebir aynı <span class=\"highlight-text\">girişim deseni</span> oluşur. Parçacığın olasılık genlikleri iki yarıktan geçerek girişim oluşturur.",
        "qs_info_observer_title": "Gözlemci Etkisi (Dalga Fonksiyonunun Çökmesi)",
        "qs_info_observer_desc": "Deneye bir <span class=\"danger-text\">dedektör</span> ekleyip hangi yarıktan geçildiğine dair bilgi elde ettiğinizde, iki yol arasındaki kuantum koherensi azalır ve girişim deseni kaybolabilir. Bu etki bilinçli bir gözlemci gerektirmez; parçacıkların dedektörle fiziksel etkileşimi yeterlidir. Parçacıklar, yine kuantum yasalarına uyar.",
        "qs_info_physics_title": "Fizik Motoru (SI Birimleri)",
