        "drake_info_r_title": "Yıldız Oluşum Hızı (R*)",
        "drake_info_r_body": "Galaksimizde her yıl kaç yıldız oluştuğunun oranı. Modern gözlemler tarafından çok iyi kısıtlanmıştır. Yaklaşık <strong>2 yıldız/yıl</strong> ",

        "drake_info_fp_title": "Gezegenli Yıldız Oranı (fp)",
        "drake_info_fp_body": "Yıldızların ne kadarının en az bir gezegeni olduğu. Kepler Uzay Teleskopunun verilerine göre neredeyse tüm yıldızların gezegenleri vardır. Yaklaşık <strong>%100 (1.0)</strong>. ",

        "drake_info_ne_title": "Yaşanabilir Gezegen Sayısı (ne)",
        "drake_info_ne_body": "Bir yıldız sistemi başına, yaşamı destekleyebilecek \"yaşanabilir bölge\" içindeki gezegen sayısı. Tahminler <strong>0.1 - 5.0</strong> arasında değişir. ",

        "drake_info_fl_title": "Yaşamın Ortaya Çıkma Olasılığı (fl)",
        "drake_info_fl_body": "Yaşanabilir bir gezegende yaşamın kendi başına ortaya çıkması olasılığı. Son derece belirsizdir. Kötümser: <strong>%0.1</strong>, İyimser: <strong>%100</strong>. ",

        "drake_info_fi_title": "Zekânın Gelişme Olasılığı (fi)",
        "drake_info_fi_body": "Yaşam ortaya çıktıktan sonra, zeki/bilinçli yaşamın gelişmesi olasılığı. Daha az belirsiz ama yine de tahmindir. Genelde <strong>%1 - %50</strong>. ",

        "drake_info_fc_title": "Teknolojik Medeniyet Olasılığı (fc)",
        "drake_info_fc_body": "Zeki yaşamın radyo iletişimini geliştirebilecek teknoloji düzeyine ulaşması olasılığı. <strong>%1 - %50</strong> arasında tahmin edilir. ",

        "drake_info_l_title": "Tespit Edilebilirlik Süresi (L)",
        "drake_info_l_body": "Medeniyetin aktif kalıp radyo sinyalleri yayıp tespit edilebilir durumda kalması süresi. En spekülatif faktör. <strong>100 yıl - 10 milyon yıl</strong> arasında tahmini. ",

        "drake_info_earth_title": "Dünya Referansı",
        "drake_info_earth_body": "<strong>Dünya</strong> 4.5 milyar yıldır var, hayat 3.8 milyar yıldır mevcut, homo sapiens ~300.000 yıldır, <strong>radyo medeniyeti ise ~100 yıldır.</strong> Eğer Dünya ortalama bir örnekse, L ~100-500.000 yıl arasında olabilir. Bu varsayımı kullanarak Drake Denkleminde orta senaryoda <strong>~2.000 medeniyet</strong> elde ederiz.",
        "drake_filter_balanced_title": "<strong>Kozmik İletişim Çağı:",
        "drake_filter_balanced_desc": "Filtre engelleri aşılabilir düzeydedir.Galaksimiz, eşzamanlı olarak var olan teknolojik açıdan gelişmiş medeniyetlerle doludur.",
        "drake_filter_behind_badge": "Filtre geride kaldı",
        "drake_filter_balanced_badge": "Dengeli evren",
        "drake_info_seti_title": "SETI & Kozmik Su Deliği (Water Hole)",
        "drake_info_seti_body": "SETI (Dünya Dışı Zekâ Araştırması) 1.420-1.666 GHz frekans bandında yapay sinyalleri arar. Bu bölge 'Su Deliği' olarak adlandırılır çünkü: Hidrojen (1.420 GHz) ve Hidroksil (1.666 GHz) ışınım çizgileri arasındadır (H + OH = H₂O). Bu bant, galaktik arka plan gürültüsünün evrendeki en düşük (en sessiz) olduğu bölgedir. Bu nedenle yıldızlararası iletişim için evrensel bir 'sessiz kanal' kabul edilir.",


