        "mc_edu_toggle": "Menü & Açıklamalar",
        "mc_edu_html": "<b>İstatistiksel Analiz ve Standart Sapma</b><br>Radyoaktif maddelerin bozunması sürekli zamanlı ve stokastik (rastgele) bir süreçtir.<br><span class=\"edu-formula\">λ = (ln 2) / t½</span><br><span class=\"highlight-orange\">🔬 Yarı Ömür Tespiti & Güven Aralığı</span><br>Bu laboratuvar, çoklu deney çalıştırdığınızda sadece ortalama almakla kalmaz. 10x, 100x veya 1000x simülasyonların <b>her birinin kendi yarı ömrünü bağımsız olarak ölçer</b>.<br><br>Daha sonra bu verilerin standart sapmasını (<b>σ</b>) ve %95 Güven Aralığını hesaplar. Deney sayısını (N) artırdıkça standart hatanın ve hata payının nasıl dramatik biçimde düştüğünü; bilimsel verilerin doğruluğunun nasıl kanıtlandığını kendiniz gözlemleyebilirsiniz.",
