        "se_reaction_singularity": "Tekillik (Singularity)",
        "se_desc_sun_cloud": "Soğuk dev moleküler gaz ve toz bulutu, kütleçekim etkisiyle kendi üzerine çöküyor. Merkezde yoğun ve sıcak bir ön-yıldız tohumu oluşuyor.",
        "se_desc_sun_main": "Kararlı hidrojen yanma evresi. Merkezdeki termonükleer füzyonun dışa doğru itme kuvveti ile kütleçekimi hidrostatik denge halindedir.",
        "se_desc_sun_red": "Çekirdekteki hidrojen tükendi. Helyum çekirdek büzülüp ısınırken, hidrojen kabuğu reaksiyonları dış katmanları devasa boyutlara şişiriyor ve yüzeyi soğutuyor.",
        "se_desc_sun_white": "Dış katmanlar gezegenimsi bulutsu olarak uzaya savruldu. Geriye kalan sıcak çekirdek, elektron dejenerasyon basıncıyla çökmekten kurtulur.",
        "se_desc_massive_cloud": "Büyük kütlesi nedeniyle gaz bulutu şiddetle çöküyor. Yüksek basınç, hidrojenin erken ve hızlı bir şekilde tutuşmasına yol açıyor.",
        "se_desc_blue_giant": "Güneş benzeri yıldızlara göre çok daha sıcak olan CNO döngüsüyle yakıtını hızlı tüketen ve yoğun radyasyon yayan parlak bir yıldız.",
        "se_desc_red_supergiant": "Çekirdekte elementler katmanlaşır. Merkeze inildikçe daha ağır elementler yanar ve yıldız demir üretim sınırına yaklaşır.",
        "se_desc_supernova": "Demir çekirdek enerji üretemez ve kütleçekimi üstün gelir. Çekirdek çökerek Tip II süpernova patlaması oluşturur.",
        "se_desc_neutron": "Proton ve elektronlar birleşerek nötronları oluşturdu. Yaklaşık 20 km çapında, Güneş'ten daha ağır bu nesne kutuplarından enerjik radyasyon jetleri yayabilir.",
        "se_desc_blue_supergiant": "Güneş'ten yüz binlerce kat parlak olan bu yıldız, yakıtını birkaç milyon yılda tüketebilir.",
        "se_desc_wolf_rayet": "Güçlü yıldız rüzgarları dış katmanları uzaya taşır; bu evrede yıldızın kütle kaybı çok yüksektir.",
        "se_desc_hypernova": "Çekirdek çöküşü çok güçlü bir patlama oluşturabilir; bazı modellerde kutuplardan gama ışını patlamaları yayılabilir.",
        "se_desc_blackhole": "Çöken çekirdek nötron dejenerasyon basıncını da aşarsa kara delik oluşabilir. Olay ufkunu geçen ışık ve bilgi dışarıya ulaşamaz.",

        // --- SİMÜLASYON SAYFASI: SCHWARZSCHILD METRİĞİ ---
        "bh_page_title": "3B Görelilik ve Kara Delik Simülasyonu",
        "bh_back_aria": "Ana Ekrana Dön",
        "bh_modal_title": "Ana Ekrana Dön",
        "bh_modal_desc": "Ana ekrana dönmek istediğinize emin misiniz?",
        "bh_cancel": "İptal",
        "bh_confirm": "Evet",
        "bh_title": "Kara Delik ve Işık Bükülmesi",
        "bh_science": "💡 Nasıl Çalışır?",
        "bh_hide": "Gizle",
        "bh_show": "Göster",
        "bh_mass": "Kara Delik Kütlesi:",
        "bh_mass_tip": "Kütle arttıkça kara deliğin çekim gücü ve gölge boyutu büyür.",
        "bh_density": "Işık Yörünge Çizgileri:",
        "bh_density_tip": "Uzayda ilerleyen ışık ışınlarının izlediği bükülmüş yollar.",
        "bh_nebula": "Arka Plan Derin Uzay (Uzak Yıldızlar)",
        "bh_disk": "Gaz Diski (Akresyon Diski)",
        "bh_photon_ring": "Foton Halkası (Işık Kapanı Sınırı)",
        "bh_rays": "3B Işık Işını Çizgileri",
        "bh_science_title": "Einstein'ın Görelilik Kuramı ile Bükülen Işık",
        "bh_intro": "Bu simülasyon, Einstein'ın Genel Görelilik Kuramı'nı kullanarak ışığın devasa bir kütleçekim etrafında nasıl büküldüğünü hesaplar.",
        "bh_sec1_title": "1. Uzay-Zamanın Bükülmesi (Schwarzschild Metriği)",
        "bh_sec1_desc": "Kara delik uzay-zaman dokusunu derin bir kuyu gibi büker. Işık uzayda aslında hep \"dümdüz\" gitmeye çalışır; fakat geçtiği uzay bükülmüş olduğu için dışarıdan bakan biri ışığın yolunun eğrildiğini görür.",
        "bh_sec2_title": "2. Gerçek Işık Yörüngeleri (Null Jeodezikler)",
        "bh_sec2_desc": "Eski tarz basit çekim kuvveti yaklaşımları yerine, bu simülasyonda ışığın izlediği tam rölativistik rotalar hesaplanır:",
        "bh_equation_label": "Denklem",
        "bh_sec2_result": "Bu denklem sayesinde kara deliğe çok yaklaşan ışıkların etrafında dönüp kaçması veya içeri çekilmesi tam fiziksel doğruluğuyla gösterilir.",
        "bh_sec3_title": "3. Foton Halkası Nedir? (Sarı Kesikli Çizgi)",
        "bh_sec3_desc": "Schwarzschild kara deliği için merkezden <code>1.5 × rₛ</code> uzaklık, foton küresinin yarıçapıdır. Buradaki ışık yörüngeleri kararsızdır: çok özel bir doğrultuda ışık kısa süre dolanabilir; küçük bir farkta ise kaçabilir veya kara deliğe düşebilir. Bu, olay ufku değildir.",
        "bh_sec4_title": "4. Gaz Diskindeki Renk ve Parlaklık Değişimleri",
        "bh_doppler": "<b>Doppler Etkisi:</b> Bize doğru yüksek hızla yaklaşan gazlar daha parlak ve mavi tonlarda görünür. Uzaklaşan taraf ise daha sönük ve kırmızıdır.",
        "bh_redshift": "<b>Kütleçekimsel Kırmızıya Kayma:</b> Kara deliğin güçlü çekim kuyusundan tırmanıp bize ulaşan ışık enerji kaybeder ve rengi kırmızıya kayar.",

