        "bio_edu_dna_title": " DNA (Deoksiribo Nükleik Asit) ve Genetik Şifre",
        "bio_edu_dna_content": "<b>DNA</b>, canlıların kalıtsal bilgilerini depolayan ve hücredeki tüm metabolik, büyüme ve bölünme süreçlerini yöneten devasa bir biyomoleküldür.<br><br><h4>İkili Sarmal (Double Helix) Yapısı</h4>Watson ve Crick tarafından keşfedilen bu yapıda, iki nükleotit zinciri birbirine ters doğrultuda (<i>Antiparalel: 5' ➔ 3' ve 3' ➔ 5'</i>) sarılarak sağ el yönlü bir sarmal oluşturur.<br><br><h4>Yapı Taşları ve Eşleşme Kuralları</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">Dış Omurga:</span> Deoksiriboz şekeri ile fosfat gruplarının <b>fosfodiester bağlarıyla</b> birbirine bağlanmasıyla oluşur.</li><li><span class=\"edu-term\">Organik Bazlar:</span> Çift halkalı Pürinler (<b>Adenin, Guanin</b>) ile tek halkalı Pirimidinler (<b>Timin, Sitozin</b>) eşleşir.</li><li><span class=\"edu-term\">Hidrojen Bağları:</span> Adenin ile Timin arasında <b>2'li zayıf H-bağı</b> (A=T), Guanin ile Sitozin arasında <b>3'lü zayıf H-bağı</b> (G≡C) kurulur. 3'lü bağ oranı arttıkça DNA'nın sıcaklığa direnci artar.</li></ul>",
        "bio_edu_prot_title": " Protein Katlanması ve Yapısal Düzeyler",
        "bio_edu_prot_content": "<b>Proteinler</b>, hücredeki enzim katalizörlüğünden yapıyı oluşturmaya, hücre içi taşımadan bağışıklık yanıtına kadar neredeyse tüm biyolojik işlevleri üstlenen moleküler makinelerdir.<br><br><h4>Proteinlerin 4 Temel Yapı Düzeyi</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">1° Birincil (Primer) Yapı:</span> Amino asitlerin peptit bağlarıyla birbirine bağlanarak oluşturduğu doğrusal zincirdir. Dizilimi genetik kod (DNA) belirler.</li><li><span class=\"edu-term\">2° İkincil (Sekonder) Yapı:</span> Peptit omurgasındaki atomlar arası hidrojen bağlarıyla zincirin <i>α-heliks</i> (sarmal) veya <i>β-kırmalı tabaka</i> şeklinde lokal kıvrımlar oluşturmasıdır.</li><li><span class=\"edu-term\">3° Üçüncül (Tersiyer) Yapı:</span> Amino asitlerin R (yan) grupları arasındaki iyonik bağlar, disülfit köprüleri, hidrofilik/hidrofobik etkileşimlerle oluşan 3 boyutlu, işlevsel küresel yapıdır.</li><li><span class=\"edu-term\">4° Dördüncül (Kuvaterner) Yapı:</span> Birden fazla polipeptit alt biriminin bir araya gelerek oluşturduğu karmaşık yapıdır (Örn: Hemoglobin, Antikorlar).</li></ul>",
        "bio_edu_rep_title": " DNA Replikasyonu (Yarı Korunumlu Kopyalanma)",
        "bio_edu_rep_content": "Hücre bölünmesi öncesinde genetik bilginin yeni hücrelere eksiksiz aktarılması için DNA'nın kendini birebir kopyalamasıdır. Meselson ve Stahl deneyiyle kanıtlandığı üzere <b>Yarı Korunumlu (Semi-conservative)</b> olarak gerçekleşir.<br><br><h4>Replikasyonda Görev Alan Enzimler</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">DNA Helikaz:</span> İki iplik arasındaki zayıf hidrojen bağlarını kırarak zincirleri ayırır ve replikasyon çatalını açar.</li><li><span class=\"edu-term\">RNA Primaz:</span> Polimerazın senteze başlayabilmesi için kalıp ipliğe kısa bir RNA primeri ekler.</li><li><span class=\"edu-term\">DNA Polimeraz:</span> Açılan kalıp ipliklerin karşısına 5' ➔ 3' yönünde yeni nükleotitler ekler. Kesintili iplikte <i>Okazaki Parçaları</i> sentezlenir.</li><li><span class=\"edu-term\">DNA Ligaz:</span> Okazaki parçacıklarını ve şeker-fosfat omurgasındaki kopuklukları fosfodiester bağlarıyla kesintisiz birleştirir.</li></ul>",
        "bio_edu_synth_title": " Santral Dogma ve Protein Sentezi",
        "bio_edu_synth_content": "Genetik bilginin <b>DNA ➔ RNA ➔ Protein</b> yönündeki akışına Santral Dogma denir. Protein sentezi iki ana evreden oluşur:<br><br><h4>1. Transkripsiyon (Yazılma)</h4>Çekirdekte RNA Polimeraz enzimi yardımıyla DNA'nın ilgili gen bölgesindeki kalıp zincirden <b>mRNA (mesajcı RNA)</b> sentezlenir. Sentez sırasında Timin yerine <b>Urasil (U)</b> bazı gelir.<br><br><h4>2. Translasyon (Okuma / Çeviri)</h4>Sitoplazmaya geçen mRNA ribozoma tutunur.<ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">Kodon:</span> mRNA üzerindeki 3'lü nükleotit dizisidir. (Başlangıç Kodonu: <b>AUG</b> / Metiyonin).</li><li><span class=\"edu-term\">Antikodon & tRNA:</span> Taşıyıcı RNA'lar antikodon bölgesiyle mRNA kodonuna bağlanır ve uygun amino asitleri ribozoma getirir.</li><li><span class=\"edu-term\">Stop Kodonları:</span> <b>UAA, UAG, UGA</b> kodonları amino asit karşılığı olmayan durdurma sinyalleridir.</li></ul>",
        "bio_edu_cell_title": " Hücre Biyolojisi ve Organel İşlevleri",
        "bio_edu_cell_content": "Hücre, canlıların bağımsız yaşam ve metabolizma gösterebilen en küçük temel birimidir.<br><br><h4>Temel Hücresel Yapılar ve Organeller</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">Hücre Zarı:</span> Akıcı Mozaik Zar Modeli. Çift katlı fosfolipit ve gömülü proteinlerden oluşur; seçici geçirgen esnek katmandır.</li><li><span class=\"edu-term\">Çekirdek (Nükleus):</span> Çift zarlı yönetim merkezidir. İçindeki çekirdekçikte (nükleolus) ribozomal RNA (rRNA) üretilir.</li><li><span class=\"edu-term\">Mitokondri:</span> Çift zarlıdır. Oksijenli solunumla hücresel ATP üreten enerji santralidir. Kendine ait DNA, RNA ve ribozomu bulunur.</li><li><span class=\"edu-term\">Granüllü ER:</span> Üzerinde ribozomlar barındırır. Hücre dışına salgılanacak proteinlerin taşınmasını ve işlenmesini sağlar.</li><li><span class=\"edu-term\">Golgi Aygıtı:</span> Yassılaşmış keselerden oluşur. Maddeleri işler, paketler, salgı keseleri ve glikoprotein/glikolipit üretir.</li><li><span class=\"edu-term\">Lizozom:</span> Hidrolitik sindirim enzimleriyle doludur. Hücre içi sindirimi gerçekleştirir ve yaşlı organelleri yok eder (otofaji).</li><li><span class=\"edu-term\">Sentrozom:</span> Dik konumlanan iki sentriyolden oluşur. Hücre bölünmesinde iğ ipliklerini organize eder.</li></ul>",

