        "rel_fact_low": "<b>Klasik Fizik Bölgesi:</b> Hızınız çok düşük olduğu için zaman genleşmesi etkisi neredeyse hissedilmez. Dünya ile aynı hızda yaşlanıyorsunuz.",
        "rel_fact_mid": "<b>Belirgin Zaman Kayması:</b> Işık hızının %{speed}'i ile seyahat ediyorsunuz. Geminizde <b>{shipTime}</b> geçerken, Dünya'daki sevdikleriniz için <b>{earthTime}</b> geçmiş olacak.",
