        // --- SİMÜLASYON SAYFASI: GALAKSİ KÜTLEÇEKİM ---
        "gal_page_title": "Galaksi Kütleçekim Simülatörü",
        "gal_performance_title": "Yüksek İşlem Performansı Gerektirir",
        "gal_performance_desc": "Bu simülasyon yüksek işlem performansı gerektirir. Özellikle düşük sistemli cihazlarda donma ve kasma yapabilir. Bunu önlemek için yıldız sayısını düşürün.",
        "gal_performance_cancel": "Kapat",
        "gal_performance_confirm": "Devam Et",
        "gal_toast_hint": "PC: Çift Tıkla / Mobil: Uzun Bas — Kara Delik Ekle!",
        "gal_ctrl_star_count": "Yıldız Sayısı (Performans)",
        "gal_ctrl_dark_matter": "Karanlık Madde Halosu Etkisi",
        "gal_btn_recreate": "Yeniden Oluştur",
        "gal_btn_clear_bh": "Kara Delikleri Temizle",
        "gal_card_spaghetti_title": "Yıldız Yutulması (Spagettileşme)",
        "gal_card_spaghetti_desc": "Bir yıldız kara deliğe çok yaklaştığında, devasa yerçekimi gücü yıldızı bir makarna gibi uzatıp parçalar. Buna bilimde <strong>\"Spagettileşme\"</strong> denir. Yıldızın gazları kara deliğe düşerken birbirine sürtünerek inanılmaz derecede ısınır. Ekranda gördüğünüz ani beyaz ve mavi parlamalar, yutulan yıldızın son anlarında yaydığı devasa enerji çığlığıdır.",
        "gal_card_dm_title": "Karanlık Madde (Görünmez Yapıştırıcı)",
        "gal_card_dm_desc": "Galaksilerin en dışındaki yıldızlar o kadar hızlı dönerler ki, normalde merkezden kopup uzaya savrulmaları gerekirdi. Bilim insanları, galaksiyi bir arada tutan ve ışık yaymayan görünmez bir kalkan olduğunu fark etti; buna <strong>Karanlık Madde</strong> diyoruz. Yukarıdaki çubuğu kaydırarak bu görünmez yapıştırıcının galaksiyi nasıl dengede tuttuğunu (veya yokluğunda nasıl dağıldığını) test edebilirsiniz.",
        "gal_card_event_horizon_title": "Olay Ufku ve Işık Halkası",
        "gal_card_event_horizon_desc": "Kara deliğin tam ortasındaki simsiyah bölge, evrendeki en hızlı şey olan ışığın bile kaçamadığı dönüşü olmayan sınır olan <strong>Olay Ufku</strong>'dur. Etrafındaki parlak ateş çemberi ise, kara deliğin muazzam çekim gücü yüzünden bükülüp onun etrafında dönmeye başlayan gaz ve ışınlardan oluşur. Kara deliğe düşen her şey, yutulmadan hemen önce bu çemberde son bir kez parlar.",

