        // --- SİMÜLASYON SAYFASI: İDEAL GAZ DENKLEMİ ---
        "ig_page_title": "LAB-PV | İdeal Gaz & Kinetik Teorik Laboratuvarı",
        "ig_back": "Ana Ekrana Dön",
        "ig_title": "İdeal Gaz & Kinetik Teorik Laboratuvarı",
        "ig_subtitle": "SI Birimleri ile Hassas Termodinamik Simülatörü",
        "ig_read_explanation": "Bilimsel Açıklamayı Oku",
        "ig_formula_constants": "k_B = 1.380649 × 10⁻²³ J/K (Boltzmann sabiti - sıcaklık ve enerji arasındaki köprü)<br>N_A = 6.02214076 × 10²³ mol⁻¹ (Avogadro sabiti - 1 moldaki parçacık sayısı)<br>R = k_B · N_A = 8.314 J/(mol·K) (ideal gaz sabiti)<br>1 atm = 101,325 Pa (deniz seviyesindeki standart atmosfer basıncı)",
        "ig_formula_scaling": "1 simülasyon topu = 1,00 × 10²² gerçek molekül<br>Gerçek molekül sayısı (N_real) = ekrandaki top sayısı × 10²²<br>Madde miktarı (mol) = gerçek molekül sayısı / Avogadro sabiti",
        "ig_formula_pressure": "Tek parçacığın itmesi = 2 × kütle × hız<br>Gerçek itme = tek parçacığın itmesi × 10²²<br>Kuvvet (F) = tüm itmelerin toplamı / geçen süre<br>Basınç (P) = kuvvet (F) / kabın toplam yüzey alanı",
        "ig_formula_distribution": "v_mp: en çok parçacığın hızı (en olası hız)<br>v_avg: tüm parçacıkların ortalama hızı<br>v_rms: fizik formüllerinde kullanılan kök-ortalama-kare hızı (enerji hesabının temeli)",
        "ig_formula_title": "TERMODİNAMİK DURUM DENKLEMİ",
        "ig_chamber": "3B Cam Deney Haznesi (İzometrik Projeksiyon)",
        "ig_parameters": "Parametre Kontrolleri",
        "ig_temperature": "Sıcaklık (T)",
        "ig_volume": "Hacim (V)",
        "ig_particles": "Simülasyon Parçacığı (N_sim)",
        "ig_gas_type": "Gaz Türü Seçimi",
        "ig_thermo_modes": "Termodinamik Deney Modları",
        "ig_boyle": "Boyle (Sabit Sıcaklık)",
        "ig_charles": "Charles (Sabit Basınç)",
        "ig_gay_lussac": "Gay-Lussac (Sabit Hacim)",
        "ig_reset": "Sıfırla",
        "ig_scaling": "Ölçekleme & Temsil Oranı",
        "ig_simulated_ball": "1 Simüle Edilen Top",
        "ig_molecules": "Molekül",
        "ig_total_molecules": "Toplam Gerçek Molekül",
        "ig_amount": "Madde Miktarı (n)",
        "ig_theoretical_pressure": "Teorik Basınç (PV=nRT)",
        "ig_measured_pressure": "Ölçülen Basınç (F/A)",
