        "tbp_sec1_title": "三体問題",
        "tbp_sec1_desc": "理想的な条件では、2つの天体の運動は閉形式の解析解として求められます。しかし3つ目の質量を加えると、一般に閉形式の解は存在せず、運動は数値的に計算されます。この系は決定論的ですが、初期条件によってはカオス的になります。初期位置や速度のごく小さな違いが、特に長い時間スケールで、大きく異なる軌道につながることがあります。",
        "tbp_sec2_title": "重力による放出と境界オプション",
        "tbp_sec2_desc": "カオス的な挙動は初期条件への敏感さを意味しますが、カオス系が必ずしも不安定とは限りません。3つの天体が近づくと速度が増加し、相互作用によって1つの天体が束縛されない軌道に入り、<strong>脱出（放出）</strong>することがあります。これはすべての初期条件で起こるわけではありません。<strong>「境界なし」</strong>ではこの可能性を観察できます。<strong>「人工境界」</strong>では、中心方向の人工的な力が天体を画面内に保ちますが、実際の重力場ではありません。",
        "tbp_sec3_title": "8の字軌道と物理的な限界",
        "tbp_sec3_desc": "これは、同じ質量を持つ3つの天体が共通の重心の周りに8の字を描く、特殊な周期解です。その存在は数学的に証明されていますが、実現には初期位置と速度を非常に正確に設定する必要があります。現実の系では、小さなずれや数値誤差、外部からの影響によって、時間とともに軌道が理想的な形からずれることがあります。",

      
        // --- SIMULATION PAGE: WAVE INTERFERENCE ---
