        "wi_controls_title": "🎛️ 実験室の操作",
        "wi_btn_move": "点を移動",
        "wi_btn_measure": "測定モード（プローブ）",
        "wi_lbl_wavelength": "波長 (λ)",
        "wi_lbl_amplitude": "振幅（強度）",
        "wi_lbl_phase": "位相差 (Δφ)",
        "wi_card1_title": "🌞 建設的干渉（腹線）",
        "wi_card1_desc1": "シミュレーション内で<strong>最も明るい（オレンジ色）</strong>、または<strong>最も暗い（濃い青色）</strong>領域です。2つの波源から来た波の山（または谷）が、これらの点で同時に出会います。",
        "wi_card1_desc2": "同じ方向へ2人が同時に押すように、波はここで力を合わせて<strong>最大の振動</strong>を生み出します。この領域を測定モードで捉えると、経路差が波長の整数倍（$\\Delta L = n\\lambda$）であることが分かります。",
        "wi_card2_title": "🌑 破壊的干渉（節線）",
        "wi_card2_desc1": "画面上に現れる静止した<strong>シアン色（青緑色）の直線</strong>です。一方の波の山が、もう一方の波の谷とここで直接ぶつかります。",
        "wi_card2_desc2": "一方の波が媒質を上へ押し、もう一方が同じ力で下へ引くため、ここでは<strong>互いに打ち消し合い（変位ゼロ）</strong>ます。この状態になるには、経路差が半整数倍でなければなりません：<span class=\"formula\">$\\Delta L = (n + \\frac{1}{2})\\lambda$</span>。ノイズキャンセリングイヤホンは、まさにこの物理原理を利用しています。",
        "wi_card3_title": "🌗 中間領域（遷移位相）",
        "wi_card3_desc": "完全な増幅でも完全な打ち消しでもありません。波の山と谷が<strong>部分的に</strong>重なる領域です。シミュレーションでは色が徐々に混ざり合い、水面は穏やかに波打ちますが、振幅が最大に達することはありません。",
        "wi_card4_title": "⏱️ 位相差とは？",
        "wi_card4_desc1": "上にある<strong>位相差</strong>スライダーを調整してみてください。これにより、一方の波源が完全に同期するのではなく、もう一方に対して少し遅れて波を発生させます。",
        "wi_card4_desc2": "タイミングが変わると、対称的なパターン全体が左右に移動する様子を観察できます。初期のタイミングが変わると、波がぶつかる空間上の位置も変化するためです。",
