        "gal_card_spaghetti_title": "恒星の潮汐破壊（スパゲッティ化）",
        "gal_card_spaghetti_desc": "恒星がブラックホールに近づきすぎると、巨大な重力によってスパゲッティのように引き伸ばされ、引き裂かれます。科学ではこれを<strong>「スパゲッティ化」</strong>と呼びます。恒星のガスがブラックホールへ落ち込む際、摩擦によって激しく加熱されます。画面に現れる突然の白と青の閃光は、恒星の最期に放出される膨大なエネルギーを表しています。",
        "gal_card_dm_title": "ダークマター（見えない接着剤）",
        "gal_card_dm_desc": "銀河の外縁にある恒星は非常に速く公転しているため、本来なら束縛を逃れて宇宙空間へ飛び出すはずです。科学者たちは、光を発しない見えない盾が銀河をまとめていることに気づき、これを<strong>ダークマター</strong>と呼びました。上のコントロールを動かして、この見えない接着剤が銀河をどのように安定させるか、または存在しない場合に銀河がどのように崩れるかを確認できます。",
        "gal_card_event_horizon_title": "事象の地平面と降着円盤",
        "gal_card_event_horizon_desc": "ブラックホールの中心にある真っ黒な領域は<strong>事象の地平面</strong>です。そこは、宇宙で最も速い光でさえ脱出できない、帰還不能の境界です。その周囲に輝くリングは、ブラックホールの巨大な重力によって曲げられ、公転するガスと放射でできています。ブラックホールへ落ち込むすべてのものは、飲み込まれる前にこのリングで最後の輝きを放ちます。",

