        "lz_page_title": "ローレンツ・アトラクター - インタラクティブなカオス",
        "lz_back_aria": "ホーム画面に戻る",
        "lz_modal_title": "ホーム画面に戻る",
        "lz_modal_desc": "ホーム画面に戻ってもよろしいですか？",
        "lz_cancel": "キャンセル",
        "lz_confirm": "はい",
        "lz_drag_hint": "画面をドラッグして回転",
        "lz_telemetry": "ローレンツ系テレメトリー",
        "lz_rho": "ロー (ρ)",
        "lz_state": "状態",
        "lz_active": "稼働中",
        "lz_warming": "準備中",
        "lz_periodic": "周期的な状態",
        "lz_chaotic": "カオス状態",
        "lz_extreme": "極端なカオス",
        "lz_title": "ローレンツ・アトラクター",
        "lz_subtitle": "カオス理論の核心",
        "lz_chaos_degree": "カオス度 (ロー: ρ)",
        "lz_periodic_preset": "周期的",
        "lz_chaotic_preset": "カオス的",
        "lz_extreme_preset": "極端なカオス",
        "lz_focus": "蝶の角度に固定",
        "lz_reset": "軌道をリセット",
        "lz_what_title": "これは何？（カオス理論）",
        "lz_what_desc": "1963年、気象学者エドワード・ローレンツはコンピューターで天気をモデル化しているとき、あることに気づきました。初期データの<strong>0.0001という丸め誤差</strong>だけでも、やがてまったく異なる天気予報を生み出すのです。このシミュレーションは、その気流を数学的に3次元空間へ投影したものです。",
        "lz_butterfly_title": "バタフライ効果",
        "lz_butterfly_desc": "<strong>「ブラジルで蝶が羽ばたくと、テキサスで竜巻が起こるかもしれない。」</strong>シミュレーションをリセットするたびに、軌道はごくわずかな違いを持って再び始まります。この二つの翼を持つ構造は<strong>「ストレンジアトラクター」</strong>と呼ばれます。常に蝶のように見えますが、軌跡が<strong>同じ形を繰り返したり、自分自身と交差したりすることはありません。</strong>そうでなければ、系は無限ループに入ってしまいます。",
        "lz_deterministic_title": "決定論的カオス",
        "lz_deterministic_desc": "この系はランダムではありません。すべてが正確な数学的規則（微分方程式）に従っています。それでも規則は非常に敏感なため、長期的な予測は不可能です。秩序からカオスが生まれ、カオスから蝶の形をした驚くべき秩序が生まれます。",
        "lz_uses_title": "どこで使われる？",
        "lz_uses_desc": "天気予報が数日間は安定していても、10日後には完全に外れてしまう理由を数学的に説明します。また、自然界の一見ランダムに見える規則的な系は、<strong>株式分析、心拍リズムの研究、流体力学（水や空気の乱流）、暗号技術</strong>にも利用されています。",

