        "bio_aa_trp": "トリプトファン",
        "bio_aa_stop": "停止",
        "bio_edu_dna_title": "DNA（デオキシリボ核酸）と遺伝暗号",
        "bio_edu_dna_content": "<b>DNA</b>は生物の遺伝情報を保存し、代謝・成長・細胞分裂を指示する巨大な生体分子です。<br><br><h4>二重らせん構造</h4>ワトソンとクリックが発見した構造では、2本のヌクレオチド鎖が逆向き（<i>逆平行: 5' ➔ 3' と 3' ➔ 5'</i>）に並び、右巻きの二重らせんを形成します。<br><br><h4>構成要素と塩基対</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">外側の骨格:</span> デオキシリボース糖とリン酸基が<strong>ホスホジエステル結合</strong>でつながっています。</li><li><span class=\"edu-term\">有機塩基:</span> 二重環のプリン（<b>アデニン、グアニン</b>）と一重環のピリミジン（<b>チミン、シトシン</b>）が対になります。</li><li><span class=\"edu-term\">水素結合:</span> アデニンとチミンは<strong>2本</strong>（A=T）、グアニンとシトシンは<strong>3本</strong>（G≡C）の弱い水素結合を形成します。</li></ul>",
        "bio_edu_prot_title": "タンパク質の折りたたみと構造レベル",
        "bio_edu_prot_content": "<b>タンパク質</b>は、酵素反応や細胞構造、細胞内輸送、免疫応答まで、ほぼすべての生物学的機能を担う分子機械です。<br><br><h4>タンパク質の4つの構造レベル</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">1° 一次構造:</span> ペプチド結合でつながったアミノ酸の直鎖で、その配列はDNAの遺伝暗号が決めます。</li><li><span class=\"edu-term\">2° 二次構造:</span> ペプチド骨格の水素結合によって、<i>αヘリックス</i>や<i>βシート</i>の局所的な折りたたみが生じます。</li><li><span class=\"edu-term\">3° 三次構造:</span> アミノ酸の側鎖間のイオン結合、ジスルフィド結合、親水性・疎水性相互作用による立体的な機能構造です。</li><li><span class=\"edu-term\">4° 四次構造:</span> 複数のポリペプチドサブユニットが集まってできる複雑な構造です（ヘモグロビン、抗体など）。</li></ul>",
