        "se_desc_sun_cloud": "冷たい巨大分子ガスと塵の雲が重力によって収縮し、中心に高密度で高温の原始星の種が形成されます。",
        "se_desc_sun_main": "安定した水素燃焼段階です。中心の熱核融合による外向きの力と重力が静水圧平衡にあります。",
        "se_desc_sun_red": "中心の水素が枯渇しました。ヘリウムコアが収縮して熱くなる一方、水素殻燃焼によって外層が大きく膨張し、表面が冷えます。",
        "se_desc_sun_white": "外層は惑星状星雲として宇宙へ放出されます。残った高温のコアは電子縮退圧によって崩壊を免れます。",
        "se_desc_massive_cloud": "大きな質量によってガス雲は激しく収縮します。高い圧力により、水素の核融合が早く激しく始まります。",
        "se_desc_blue_giant": "太陽型星よりはるかに高温で、CNOサイクルによって燃料を急速に消費し、強い放射を放つ明るい星です。",
        "se_desc_red_supergiant": "コアには元素が層状に形成されます。中心へ向かうほど重い元素が燃焼し、星は鉄を作れる限界に近づきます。",
        "se_desc_supernova": "鉄のコアはエネルギーを生み出せないため、重力が勝ります。崩壊するコアがII型超新星爆発を起こします。",
        "se_desc_neutron": "陽子と電子が結合して中性子を形成します。直径約20 kmで太陽より重いこの天体は、両極から高エネルギー放射のジェットを放つことがあります。",
        "se_desc_blue_supergiant": "太陽の数十万倍も明るく、わずか数百万年で燃料を使い果たすことがあります。",
        "se_desc_wolf_rayet": "強力な恒星風が外層を宇宙へ運び去るため、この段階では質量損失率が非常に高くなります。",
        "se_desc_hypernova": "コア崩壊によって非常に強力な爆発が起こり、一部のモデルでは両極からガンマ線バーストが放出されると予測されています。",
        "se_desc_blackhole": "崩壊するコアが中性子縮退圧を超えると、ブラックホールが形成されることがあります。事象の地平面の内側からは光も情報も脱出できません。",

