        "aurora_info_toggle_close": "閉じる",
        "aurora_panel_title": "太陽とIMF B<sub>z</sub>のオーロラ物理",
        "aurora_panel_desc": "3D磁気リコネクションと宇宙天気モデル。",
        "aurora_lbl_speed": "太陽風の速度 (v)",
        "aurora_lbl_bz": "IMF B<sub>z</sub>（極性）",
        "aurora_lbl_count": "粒子密度",
        "aurora_lbl_field": "磁力線",
        "aurora_lbl_shock": "バウショックと磁気尾",
        "aurora_tele_reconn": "リコネクション:",
        "aurora_reconn_active": "有効（南向き）",
        "aurora_reconn_inactive": "無効（北向き）",
        "aurora_tele_power": "オーロラ出力指数:",
        "aurora_btn_reset_cam": "カメラをリセット",
        "aurora_legend_shock": "バウショック波",
        "aurora_legend_tail": "磁気尾プラズマ",
        "aurora_legend_storm": "強い嵐の放射（赤 / ピンク）",
        "aurora_info_main_title": "オーロラと磁気圏の物理",
        "aurora_sec1_title": "1. 太陽風とIMF B<sub>z</sub>とは？",
        "aurora_sec1_desc": "太陽は超音速で荷電プラズマを宇宙へ放出します。このプラズマは太陽の磁場も宇宙へ運びます。これが<strong>惑星間磁場（IMF）</strong>です。<strong>B<sub>z</sub></strong>は、地球に届くこの磁場の南北（Z軸）方向を表します。",
        "aurora_sec2_title": "2. 磁気シールドとバウショック",
        "aurora_sec2_desc": "地球の磁気圏は、荷電した太陽プラズマから守る巨大な見えない盾として働きます。400～1000 km/sで近づく太陽風がこの盾に衝突すると急減速し、超音速機が前方の空気を圧縮するように、地球の前方に明るい黄色の<strong>バウショック</strong>を形成します。",
        "aurora_sec3_title": "3. B<sub>z</sub>が負のとき、なぜ嵐が起こる？",
        "aurora_sec3_desc": "太陽側を向く地球の磁場は常に<strong>北</strong>を指しています。太陽から来るB<sub>z</sub>成分が<strong>南（負）</strong>を指すと、反対向きの磁極が引き合います。磁場がつなぎ替わる<strong>磁気リコネクション</strong>が起こり、盾に「開いた扉」ができて荷電した太陽プラズマが直接入り込みます。",
        "aurora_sec4_title": "4. なぜオーロラは強くなる？",
        "aurora_sec4_desc": "侵入したプラズマは、盾の後方にある<strong>磁気尾</strong>へ運ばれます。B<sub>z</sub>が負になるほど（例：-15 nT）、より多くのエネルギーが磁気尾に蓄積します。やがてこのエネルギーが巨大な電磁スリングショット（ローレンツ力）のように放出され、何百万もの荷電粒子を地球の極へ向けて飛ばします。嵐が強まると電子の流量とエネルギーが増え、オーロラオーバルが広がり、光が明るくなります。",
        "aurora_sec5_title": "💡 大気との衝突と色",
        "aurora_sec5_desc": "極地方へ飛ばされた電子は大気中の気体分子と衝突し、光子を放出させます。<br><br>• <b>緑 / シアン:</b> 高度約100～150 kmで酸素（O）原子と衝突して生じます。<br><br>• <b>赤 / ピンク:</b> 強い地磁気嵐（太陽風が速く、B<sub>z</sub>が非常に負）の際、エネルギーの高い電子がより深く入り、高高度（300 km以上）の希薄な酸素や低高度（100 km未満）の濃い窒素（N<sub>2</sub>）分子を励起します。強く負のB<sub>z</sub>で現れる赤い放射は、高エネルギーの嵐を示します。",

