        "ig_subtitle": "SI単位による高精度熱力学シミュレーター",
        "ig_read_explanation": "科学的な説明を読む",
        "ig_formula_constants": "k_B = 1.380649 × 10⁻²³ J/K（ボルツマン定数 - 温度とエネルギーを結ぶ定数）<br>N_A = 6.02214076 × 10²³ mol⁻¹（アボガドロ定数 - 1 mol中の粒子数）<br>R = k_B · N_A = 8.314 J/(mol·K)（理想気体定数）<br>1 atm = 101,325 Pa（海面での標準大気圧）",
        "ig_formula_scaling": "シミュレーションのボール1個 = 実際の分子 1.00 × 10²²個<br>実際の分子数 (N_real) = 画面上のボール数 × 10²²<br>物質量 (mol) = 実際の分子総数 / アボガドロ定数",
        "ig_formula_pressure": "1粒子の衝撃量 = 2 × 質量 × 速度<br>実際の衝撃量 = 1粒子の衝撃量 × 10²²<br>力 (F) = 全衝撃量の合計 / 経過時間<br>圧力 (P) = 力 (F) / 容器の総表面積",
        "ig_formula_distribution": "v_mp: 粒子が最も多い速度（最頻速度）<br>v_avg: 全粒子の平均速度<br>v_rms: 物理公式で使われる二乗平均平方根速度（エネルギー計算の基礎）",
