        "drake_info_fi_title": "知性が発達する割合 (fi)",
        "drake_info_fi_body": "生命が発生した後に、知的または意識を持つ生命が発達する確率。推測的ですが、一般に<strong>1～50%</strong>と推定されます。",
        "drake_info_fc_title": "技術を持つ割合 (fc)",
