        "drake_info_l_title": "技術文明の存続期間 (L)",
        "drake_info_l_body": "文明が活動し、検出可能な電波信号を発信し続ける期間。最も推測的な要素で、推定値は<strong>100年～1000万年</strong>です。",
        "drake_info_earth_title": "地球との比較",
        "drake_info_earth_body": "<strong>地球</strong>は45億年前に形成され、生命は38億年前から存在し、ホモ・サピエンスは約30万年前に現れ、<strong>電波文明は約100年</strong>です。地球が平均的なら、Lは約100～50万年かもしれません。この仮定で中間シナリオを計算すると、<strong>約2,000文明</strong>になります。",
        "drake_info_seti_title": "SETIと宇宙のウォーターホール",
        "drake_info_seti_body": "SETI（地球外知的生命探査）は1.420～1.666 GHz帯で人工信号を探します。水素（1.420 GHz）とヒドロキシル（1.666 GHz）の線の間（H + OH = H₂O）にあるため「ウォーターホール」と呼ばれます。この静かな周波数帯は、知的文明が通信を探す自然な窓です。",

