        "seti_report_von_explanation": "<strong>何が見える？</strong> 青い点は到達した恒星系、リングは新しい系へ到着するプローブを示します。プローブ速度が高いほど遠方へ到達しやすくなりますが、新しい系でプローブを生産するには50年かかります。",
