        "seti_report_dark_note": "<strong>どう読めばいい？</strong> 応答確率は観測結果ではありません。送信出力、帯域幅、受信機温度が信号の検出可能性を決め、応答設定がその後の動きを決めます。",
        "seti_report_dyson_title": "ダイソン・スウォームと光度曲線",
        "seti_report_dyson_summary": "<strong>これは何？</strong> 恒星の周囲でエネルギーを集める文明が、遠方からどのように見えるかを可視化します。",
        "seti_report_dyson_explanation": "<strong>なぜ光は数パーセントしか減らない？</strong> パネルがすべて同時に恒星の前を通るわけではなく、各パネルが覆う恒星面の割合も小さいためです。この設定では数パーセントの減少が正常です。",
        "seti_report_dyson_note": "<strong>なぜIR値は小さい？</strong> パネルが捕捉するのは恒星の総光量の一部だけです。これは実際の赤外線スペクトルではなく、捕捉エネルギーの正規化推定値です。",

        // --- SIMULATION PAGE: KARDASHEV SCALE SIMULATION ---
        "ks_page_title": "カルダシェフ・スケールシミュレーター - V2",
