        "ks_fact_current": "人類は現在、タイプ0の段階にあります。エネルギーの大部分を化石燃料と核分裂から得ています。タイプ1に到達するまで、およそ100～200年かかる可能性があります。",
        "ks_fact_type0_title": "タイプ0文明",
        "ks_fact_type0": "惑星に届く太陽エネルギーをすべて利用できず、地質現象や大気現象を完全には制御できません。",
        "ks_fact_type1_title": "タイプ1：惑星文明",
        "ks_fact_type1": "惑星に届くすべてのエネルギーに加え、気候と地質も制御できます。核融合エネルギーと宇宙エレベーターが標準技術になります。",
        "ks_fact_dyson_title": "移行段階：ダイソン・スウォーム",
        "ks_fact_dyson": "惑星のエネルギー利用は限界に達しました。文明は巨大な太陽光パネルを備えた衛星によって恒星のエネルギーを集め始めます。",
        "ks_fact_type2_title": "タイプ2：恒星文明",
        "ks_fact_type2": "ダイソン球が完成しています。恒星が生み出す全エネルギーを損失なく利用し、近隣の太陽系にある惑星を簡単に移動させられます。",
        "ks_fact_type3_title": "タイプ3：銀河文明（神に近い存在）",
        "ks_fact_type3": "銀河全体のエネルギーを操作し、ブラックホールからエネルギーを取り出し、時空の幾何学を曲げられます。私たちには物理法則を超越した存在に見えます。",
        "ks_type0": "タイプ0",
        "ks_type1": "タイプ1",
        "ks_type15": "タイプ1.5",
