        "seti_von_fact_title": "How Does It Work? (Distance and Time Model)",
        "seti_von_fact_desc": "Each colonization event is scheduled using the distance between stars divided by probe speed, plus 50 years of production time. The stars form a representative 200-light-year disk, so this is not a prediction for the real galaxy.",
