        "lz_drag_hint": "Drag the Screen to Rotate",
        "lz_telemetry": "Lorenz System Telemetry",
        "lz_rho": "Rho (ρ)",
        "lz_state": "State",
        "lz_active": "ACTIVE",
        "lz_warming": "WARMING UP",
        "lz_periodic": "Periodic Regime",
        "lz_chaotic": "Chaotic Regime",
        "lz_extreme": "Extreme Chaos",
        "lz_title": "Lorenz Attractor",
        "lz_subtitle": "The Heart of Chaos Theory",
        "lz_chaos_degree": "Chaos Degree (Rho: ρ)",
        "lz_periodic_preset": "Periodic",
        "lz_chaotic_preset": "Chaotic",
        "lz_extreme_preset": "Extreme Chaos",
        "lz_focus": "Lock to Butterfly Angle",
        "lz_reset": "Reset Trajectory",
        "lz_what_title": "What Is It? (Chaos Theory)",
        "lz_what_desc": "In 1963, meteorologist Edward Lorenz noticed something while modeling weather on a computer: even a <strong>0.0001 rounding error</strong> in the initial data eventually produced a completely different weather forecast. This simulation is a mathematical projection of those air currents into three-dimensional space.",
        "lz_butterfly_title": "The Butterfly Effect",
        "lz_butterfly_desc": "<strong>\"A butterfly flapping its wings in Brazil can cause a tornado in Texas.\"</strong> This is a metaphor for how small initial differences can grow in chaotic systems, not a direct law of causation. The two-winged geometry of the Lorenz system is called a <strong>strange attractor</strong>. Its trajectory does not intersect itself in three-dimensional phase space; apparent crossings in a 2D drawing can result from projection.",
        "lz_deterministic_title": "Deterministic Chaos",
        "lz_deterministic_desc": "This system is not random! Everything follows precise mathematical rules (differential equations). Yet the rules are so sensitive that long-term prediction is impossible. Chaos emerges from order, and remarkable order emerges from chaos in the shape of a butterfly.",
        "lz_uses_title": "Where Is It Used?",
        "lz_uses_desc": "It mathematically explains why weather forecasts remain consistent for only a few days and fail completely after ten days. Nature's seemingly random but rule-based systems are also used in <strong>stock analysis, heart-rhythm studies, fluid mechanics (water and air turbulence), and encryption technologies.</strong>",

        // --- GENERAL MODAL AND INTERFACE ---
