        // --- SIMULATION PAGE: AURORA (NORTHERN LIGHTS) ---
        "aurora_page_title": "Sun, IMF Bz & Magnetotail Aurora Simulation",
        "aurora_panel_toggle_hide": "Hide Panel",
        "aurora_panel_toggle_show": "Show Panel",
        "aurora_info_toggle_guide": "Aurora Guide",
        "aurora_info_toggle_close": "Close",
        "aurora_panel_title": "Sun & IMF B<sub>z</sub> Aurora Physics",
        "aurora_panel_desc": "3D Magnetic Reconnection & Space Weather Model.",
        "aurora_lbl_speed": "Solar Wind Speed (v)",
        "aurora_lbl_bz": "IMF B<sub>z</sub> (Polarity)",
        "aurora_lbl_count": "Particle Density",
        "aurora_lbl_field": "Magnetic Field Lines",
        "aurora_lbl_shock": "Bow Shock & Tail",
        "aurora_tele_reconn": "Reconnection:",
        "aurora_reconn_active": "Active (Southward)",
        "aurora_reconn_inactive": "Inactive (Northward)",
        "aurora_tele_power": "Auroral Power Index:",
        "aurora_btn_reset_cam": "Reset Camera",
        "aurora_legend_shock": "Bow Shock Wave",
        "aurora_legend_tail": "Magnetotail Plasma Tail",
        "aurora_legend_storm": "Severe Storm Emission (Red / Pink)",
        "aurora_info_main_title": "Aurora & Magnetosphere Physics",
        "aurora_sec1_title": "1. What is Solar Wind and IMF B<sub>z</sub>?",
        "aurora_sec1_desc": "The Sun ejects charged plasma into space at supersonic speeds. This plasma drags the Sun's magnetic field with it into space, known as the <b>Interplanetary Magnetic Field (IMF)</b>. <b>B<sub>z</sub></b> represents the North-South (Z-axis) orientation of this magnetic field as it reaches Earth.",
        "aurora_sec2_title": "2. Magnetic Shield and Bow Shock",
        "aurora_sec2_desc": "Earth's magnetic field is generated mainly by the geodynamo: motion of conducting fluid in the outer core. It creates the magnetosphere, which acts as a protective region against charged solar plasma. When the solar wind arrives at supersonic speed, a <b>bow shock</b> forms on Earth's sunward side.",
        "aurora_sec3_title": "3. Why Do Storms Trigger When B<sub>z</sub> is Negative?",
        "aurora_sec3_desc": "When the solar-wind B<sub>z</sub> component points south, or negative, conditions can favor magnetic reconnection with Earth's field. This can increase energy and particle transfer, but the magnetosphere does not disappear and the plasma does not simply flow straight inside.",
        "aurora_sec4_title": "4. Why Do Auroras Intensify?",
        "aurora_sec4_desc": "Energy transferred from the solar wind can accumulate in the <b>magnetotail</b>. Negative B<sub>z</sub> generally increases energy input, but the response depends on more than B<sub>z</sub> alone. Energy releases in the tail can direct particles toward the poles, contributing to an expanded auroral oval and brighter aurora.",
        "aurora_sec5_title": "💡 Atmospheric Collisions and Colors",
        "aurora_sec5_desc": "Energetic particles directed toward the polar regions excite atoms and molecules in the atmosphere; light is emitted as they return to lower energy states:<br><br>• <b>Green:</b> Emissions from excited atomic oxygen are prominent at altitudes of approximately 100–150 km.<br><br>• <b>Red:</b> Red emissions are especially associated with sparse atomic oxygen at high altitudes. Nitrogen and molecular nitrogen ions can also contribute blue, purple, and reddish tones. Color alone cannot determine storm intensity with certainty.",

        // --- SIMULATION PAGE: ADVANCED QUANTUM INTERFERENCE ---
        "qs_title": "Advanced Quantum Interference Simulation",
        "qs_heading": "Advanced Quantum Simulation",
        "qs_lbl_particle_type": "Particle Type:",
        "qs_opt_photon": "Light (Photon) - Massless",
        "qs_opt_electron": "Matter (Electron) - Massive",
        "qs_lbl_view_mode": "View Mode:",
        "qs_opt_wave": "Classical Wave Mode",
        "qs_opt_quantum": "Quantum Particle Mode",
        "qs_lbl_exp_mode": "Experiment Mode:",
