        "se_desc_sun_cloud": "A cold giant molecular gas and dust cloud collapses under gravity, forming a dense, hot protostellar seed at its center.",
        "se_desc_sun_main": "Stable hydrogen-burning phase. Thermonuclear fusion in the core and gravity are in hydrostatic equilibrium.",
        "se_desc_sun_red": "Hydrogen in the core is exhausted. The helium core contracts and heats up while hydrogen-shell burning expands and cools the outer layers.",
