        "se_desc_supernova": "An iron core cannot generate energy, so gravity wins. The collapsing core produces a Type II supernova.",
        "se_desc_neutron": "Protons and electrons combine to form neutrons. This object is about 20 km across and can emit energetic radiation jets from its poles.",
        "se_desc_blue_supergiant": "Hundreds of thousands of times brighter than the Sun, this star can consume its fuel in only a few million years.",
