        "bio_org_nucleus_name": "Nucleus",
        "bio_org_nucleus_desc": "Management center containing DNA. Double-membraned structure containing the nucleolus and chromatin network.",
        "bio_org_mito_name": "Mitochondria",
        "bio_org_mito_desc": "The power plant (ATP production) of the cell. Possesses a folded inner membrane (cristae) inside a transparent outer membrane.",
        "bio_org_er_name": "Rough Endoplasmic Reticulum",
        "bio_org_er_desc": "A membranous network surrounding the nucleus involved in material transport. Ribosomes attached to its surface synthesize proteins.",
        "bio_org_golgi_name": "Golgi Apparatus",
        "bio_org_golgi_desc": "Modifies, packages into vesicles, and targets secretory proteins and lipids.",
        "bio_org_lyso_name": "Lysosome",
