        "bio_org_centro_name": "Centrosome (Centrioles)",
        "bio_org_centro_desc": "Organizes microtubules and spindle fibers during cell division in animal cells.",

        "bio_toast_rep_success": "Replication Successful! Leading and Lagging (Okazaki) strands synthesized.",
