        "bio_base_G_name": "Guanine (G)",
        "bio_base_G_desc": "Purine base. Forms 3 hydrogen bonds with Cytosine.",
        "bio_base_C_name": "Cytosine (C)",
        "bio_base_C_desc": "Pyrimidine base. Forms 3 hydrogen bonds with Guanine.",

        "bio_aa_met": "Methionine (Start)",
        "bio_aa_val": "Valine",
        "bio_aa_phe": "Phenylalanine",
        "bio_aa_pro": "Proline",
        "bio_aa_trp": "Tryptophan",
        "bio_aa_stop": "Stop",

        "bio_edu_dna_title": " DNA (Deoxyribonucleic Acid) & Genetic Code",
        "bio_edu_dna_content": "<b>DNA</b> is a vast biomolecule that stores genetic information and directs all metabolic, growth, and division processes in living organisms.<br><br><h4>Double Helix Structure</h4>Discovered by Watson and Crick, two nucleotide chains run in opposite directions (<i>Antiparallel: 5' ➔ 3' and 3' ➔ 5'</i>) coiling into a right-handed double helix.<br><br><h4>Building Blocks & Base Pairing</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">Outer Backbone:</span> Formed by deoxyribose sugars and phosphate groups linked via <b>phosphodiester bonds</b>.</li><li><span class=\"edu-term\">Organic Bases:</span> Double-ring Purines (<b>Adenine, Guanine</b>) pair with single-ring Pyrimidines (<b>Thymine, Cytosine</b>).</li><li><span class=\"edu-term\">Hydrogen Bonds:</span> <b>2 hydrogen bonds</b> pair Adenine with Thymine (A=T), while <b>3 hydrogen bonds</b> pair Guanine with Cytosine (G≡C). Higher G-C content increases thermal stability.</li></ul>",
        "bio_edu_prot_title": " Protein Folding & Structural Levels",
        "bio_edu_prot_content": "<b>Proteins</b> are molecular machines executing nearly all biological tasks, from enzyme catalysis and cellular structure to intracellular transport and immune defense.<br><br><h4>4 Structural Levels of Proteins</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">1° Primary Structure:</span> Linear sequence of amino acids joined by peptide bonds, encoded directly by DNA.</li><li><span class=\"edu-term\">2° Secondary Structure:</span> Local folding patterns such as <i>α-helices</i> and <i>β-pleated sheets</i> stabilized by hydrogen bonds in the peptide backbone.</li><li><span class=\"edu-term\">3° Tertiary Structure:</span> 3D functional conformation formed by ionic bonds, disulfide bridges, and hydrophobic/hydrophilic interactions among amino acid R-groups.</li><li><span class=\"edu-term\">4° Quaternary Structure:</span> Complex multi-subunit assembly of multiple polypeptide chains (e.g., Hemoglobin, Antibodies).</li></ul>",
        "bio_edu_rep_title": " DNA Replication (Semi-Conservative)",
        "bio_edu_rep_content": "The process by which DNA duplicates its genetic code prior to cell division. Proven by the Meselson-Stahl experiment, replication is <b>Semi-Conservative</b>.<br><br><h4>Key Enzymes in Replication</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">DNA Helicase:</span> Unwinds the double helix by breaking weak hydrogen bonds between base pairs, forming the replication fork.</li><li><span class=\"edu-term\">RNA Primase:</span> Lays down short RNA primers required for DNA Polymerase to initiate synthesis.</li><li><span class=\"edu-term\">DNA Polymerase:</span> Adds complementary nucleotides in the 5' ➔ 3' direction. Synthesizes <i>Okazaki fragments</i> on the lagging strand.</li><li><span class=\"edu-term\">DNA Ligase:</span> Joins Okazaki fragments and seals breaks in the sugar-phosphate backbone via phosphodiester bonds.</li></ul>",
        "bio_edu_synth_title": " Central Dogma & Protein Synthesis",
        "bio_edu_synth_content": "The directional flow of genetic information: <b>DNA ➔ RNA ➔ Protein</b>. Protein synthesis consists of two major phases:<br><br><h4>1. Transcription</h4>In the nucleus, RNA Polymerase uses a DNA gene template strand to synthesize <b>messenger RNA (mRNA)</b>, substituting <b>Uracil (U)</b> for Thymine.<br><br><h4>2. Translation</h4>mRNA enters the cytoplasm and docks onto a ribosome. <ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">Codon:</span> A triplet nucleotide sequence on mRNA (Start Codon: <b>AUG</b> / Methionine).</li><li><span class=\"edu-term\">Anticodon & tRNA:</span> Transfer RNAs match their anticodon loop to the mRNA codon, delivering corresponding amino acids to the ribosome.</li><li><span class=\"edu-term\">Stop Codons:</span> <b>UAA, UAG, UGA</b> signal the termination of translation.</li></ul>",
        "bio_edu_cell_title": " Cell Biology & Organelle Functions",
        "bio_edu_cell_content": "The cell is the basic structural and functional unit of all living organisms.<br><br><h4>Key Cellular Structures & Organelles</h4><ul style=\"margin-top:5px; padding-left:20px;\"><li><span class=\"edu-term\">Cell Membrane:</span> Fluid Mosaic Model. Phospholipid bilayer with embedded proteins providing selective permeability.</li><li><span class=\"edu-term\">Nucleus:</span> Double-membraned control center housing DNA. Contains the nucleolus for ribosomal RNA (rRNA) assembly.</li><li><span class=\"edu-term\">Mitochondria:</span> Double-membraned powerhouses producing cellular ATP via aerobic respiration. Contains its own DNA and ribosomes.</li><li><span class=\"edu-term\">Rough ER:</span> Studded with ribosomes; processes and transports proteins destined for secretion or membrane insertion.</li><li><span class=\"edu-term\">Golgi Apparatus:</span> Stacked flattened sacs that modify, sort, and package proteins into secretory vesicles.</li><li><span class=\"edu-term\">Lysosome:</span> Packed with hydrolytic enzymes for intracellular digestion and organelle degradation (autophagy).</li><li><span class=\"edu-term\">Centrosome:</span> Contains two perpendicular centrioles that organize spindle fibers during cell division.</li></ul>",

