// Keep critical scientific explanations consistent across all language blocks.
const scientificTextCorrections = {
    tr: {
        sir_isolation_info: "<strong>🏠 Modelde izolasyon:</strong> Hastalanan bireyler, seçilen orana göre evde tutulur; bu, simülasyonda bulaşma olasılığını azaltır ancak gerçek hayatta bulaşmayı tamamen ortadan kaldırmayabilir.",
        sir_recovered_info: "<strong>■ İyileşen (Yeşil):</strong> Hastalıktan sonra simülasyonda yeniden enfekte olmayan bireyler; bu, modelin bağışıklık varsayımıdır.",
        dp_card1_desc: "Birinci kol aşağı salınırken enerjisi eklem üzerinden ikinci kola aktarılır; ancak enerjinin tamamı aktarılmaz, iki kolun hareketleri arasında paylaşılır. Bu doğrusal olmayan enerji aktarımı, ikinci kolun bazen çok büyük açısal hızlara ulaşmasına yol açabilir.",
        dp_card2_title: "Kaotik Hareket (Yörüngelerin Görünür Kesişmesi)",
        dp_card2_desc: "Ekrandaki izler üst üste binebilir. Aynı konum ve hızlara sahip tam fiziksel durum yeniden oluşursa hareket periyodik olur; ideal çift sarkaçta özel başlangıç koşullarıyla bu mümkündür. Kaotik durumda ise küçük başlangıç farkları zamanla büyür ve uzun vadeli tahmini zorlaştırır.",
        lz_butterfly_desc: "<strong>\"Brezilya'daki bir kelebeğin kanat çırpması, Teksas'ta bir kasırgaya neden olabilir.\"</strong> Bu, kaotik sistemlerde küçük başlangıç farklarının büyüyebilmesini anlatan bir benzetmedir; doğrudan bir nedensellik yasası değildir. Lorenz sisteminin iki kanatlı geometrisi <strong>garip çeker</strong> olarak adlandırılır. Üç boyutlu faz uzayındaki yörünge kendi kendisiyle kesişmez; iki boyutlu çizimde görülen kesişmeler izdüşümden kaynaklanabilir.",
        aurora_sec2_desc: "Dünya'nın manyetik alanı, esas olarak dış çekirdekteki iletken sıvı hareketlerinin oluşturduğu jeodinamo ile üretilir ve manyetosferi oluşturur. Bu manyetosfer yüklü güneş plazmasına karşı koruyucu bir bölge görevi görür. Güneş rüzgarı süpersonik hızla geldiğinde, Dünya'nın ön tarafında bir <b>şok dalgası (bow shock)</b> oluşur.",
        aurora_sec3_desc: "Güneş rüzgarındaki B<sub>z</sub> bileşeni güneye, yani negatif yönde olduğunda, Dünya'nın manyetik alanıyla uygun koşullarda manyetik yeniden bağlanma kolaylaşır. Bu süreç enerji ve parçacık aktarımını artırabilir; ancak manyetosfer tamamen ortadan kalkmaz ve plazma basitçe doğrudan içeri akmaz.",
        aurora_sec4_desc: "Güneş rüzgarıyla aktarılan enerji manyetosferin arka tarafındaki <b>manyetik kuyrukta (magnetotail)</b> depolanabilir. Negatif B<sub>z</sub> genellikle enerji girişini artırır; fakat etki yalnızca B<sub>z</sub>'ye bağlı değildir. Kuyruktaki enerji boşalmaları, parçacıkları kutuplara yönlendirerek auroral ovalin genişlemesine ve auroranın parlaklaşmasına katkıda bulunabilir.",
        qs_info_observer_desc: "Deneye bir <span class=\"danger-text\">dedektör</span> ekleyip hangi yarıktan geçildiğine dair bilgi elde ettiğinizde, iki yol arasındaki kuantum koherensi azalır ve girişim deseni kaybolabilir. Bu etki bilinçli bir gözlemci gerektirmez; parçacıkların dedektörle fiziksel etkileşimi yeterlidir. Parçacıklar klasik bilardo toplarına dönüşmez, yine kuantum yasalarına uyar.",
        bh_sec3_desc: "Schwarzschild kara deliği için merkezden <code>1.5 × rₛ</code> uzaklık, foton küresinin yarıçapıdır. Buradaki ışık yörüngeleri kararsızdır: çok özel bir doğrultuda ışık kısa süre dolanabilir; küçük bir farkta ise kaçabilir veya kara deliğe düşebilir. Bu, olay ufku değildir.",
        gal_card_dm_desc: "Galaksilerin dış yıldızlarının hareketi, yalnızca görünen maddeden beklenenden farklıdır. Gözlemler bu farkı açıklamak için ışıkla etkileşimi çok zayıf olan karanlık madde bileşeninin ek kütleçekim etkisine işaret eder. Çubuk, bu etkinin modeldeki sonucunu gösterir; karanlık madde doğrudan gözlenmiş bir yapıştırıcı veya kalkan değildir.",
        ig_formula_pressure: "Tek parçacığın duvara aktardığı itki, elastik çarpışmada duvar doğrultusundaki hız bileşeniyle yaklaşık 2 × kütle × dik hızdır.<br>Gerçek itki = tek parçacık itkisi × 10²²<br>Kuvvet (F) = toplam itki / geçen süre<br>Basınç (P) = kuvvet (F) / yüzey alanı",
        ig_intro: "Bu simülasyon SI birimleriyle ideal gaz modelini gösterir. Ekrandaki parçacıklar gerçek molekül gruplarını temsil eden bir ölçekleme kullanır; amaç, makroskobik gaz yasalarının mikroskobik hareket ve duvar çarpışmalarından nasıl ortaya çıktığını göstermektir.",
        ig_scaling_text: "Gerçek bir kapta molekül sayısı çok büyüktür. Bu nedenle ekrandaki her top, modelde seçilmiş bir temsil oranıyla çok sayıda molekülü temsil eder. Bu oran doğanın sabiti değil, simülasyonun kaba ölçekleme tercihidir.",
        se_legend_singularity: "⚛️ Tekillik (klasik modelin sınırı)",
        se_desc_supernova: "Demir çekirdeğin füzyonu enerji sağlamaz ve çekirdek çökebilir. Hidrojen zarfının korunup korunmadığına bağlı olarak farklı tipte çekirdek çökmesi süpernovaları oluşabilir; bu model Tip II örneğini gösterir.",
        se_desc_neutron: "Çekirdek çökmesi sırasında elektron yakalanması proton ve elektron sayısını azaltarak nötronca zengin madde oluşturur. Yaklaşık 20 km çapındaki nötron yıldızları güçlü manyetik alanlara sahip olabilir; bazıları kutuplarından ışınım demetleri veya jetler yayar.",
        ks_fact_current: "İnsanlığın Kardaşev düzeyi için yaklaşık K ≈ 0,73 değeri, seçilen enerji tanımına bağlı bir tahmindir; evrensel olarak kabul edilmiş kesin bir ölçüm değildir. Tip 1'e ne zaman ulaşılacağı bilinmiyor.",
        ks_fact_type1: "Kardaşev Tip 1, gezegen ölçeğindeki enerjiyi kullanabilen bir uygarlık fikridir. İklimi ve jeolojiyi bütünüyle kontrol edebilmesi ya da füzyon ve uzay asansörlerinin standart olması ölçeğin zorunlu sonucu değil, spekülatif bir yorumdur.",
        ks_fact_type2: "Tip 2, yıldız ölçeğinde enerji kullanabilen varsayımsal bir uygarlığı ifade eder. Dyson küresi zorunlu değildir; pratik tartışmalarda kısmi bir Dyson sürüsü daha gerçekçi bir örnektir. Enerjinin tümünü kayıpsız kullanmak fiziksel bir varsayımdır.",
        ks_fact_type3: "Tip 3, galaksi ölçeğinde enerji kullanımını anlatan spekülatif bir sınıftır. Kara deliklerden enerji çıkarma gibi fikirler fizik kurallarıyla otomatik olarak çelişmez; ancak uzay-zamanı bükmek veya fizik kurallarını aşmak bu ölçeğin kanıtlanmış sonucu değildir."
    },
    ja: {
        sir_isolation_info: "<strong>🏠 モデル上の隔離:</strong> 感染者は選択した割合に応じて自宅に留まります。シミュレーションでは感染確率を下げますが、現実の隔離が感染を完全に防ぐとは限りません。",
        sir_recovered_info: "<strong>■ 回復者（緑）:</strong> シミュレーション内で再感染しない人々です。これはモデルが置く免疫の仮定を表します。",
        dp_card1_desc: "最初の腕が下へ振れると、エネルギーの一部が関節を通じて2本目の腕へ移ります。エネルギーは両方の腕の運動に分配され、この非線形な移動によって2本目の腕が大きな角速度に達することがあります。",
        dp_card2_title: "カオス的運動（軌跡の見かけの交差）",
        dp_card2_desc: "軌跡は画面上で重なって見えることがあります。完全な物理状態が同じ位置と速度に戻れば運動は周期的になり、特別な初期条件ではそれが起こります。カオス的な場合は小さな初期差が時間とともに増大し、長期予測を難しくします。",
        lz_butterfly_desc: "<strong>「ブラジルで蝶が羽ばたくと、テキサスで竜巻が起こるかもしれない。」</strong>これは、カオス系で小さな初期差が増幅されることの比喩であり、直接的な因果法則ではありません。ローレンツ系の二つの翼のような形は<strong>ストレンジアトラクター</strong>と呼ばれます。3次元の位相空間では軌跡は自己交差しませんが、2次元への投影では交差して見えることがあります。",
        aurora_sec2_desc: "地球の磁場は主に、外核の導電性流体の運動によるジオダイナモで生じ、磁気圏を形成します。磁気圏は荷電した太陽プラズマに対する保護領域です。太陽風が超音速で到達すると、地球の太陽側に<strong>バウショック</strong>が形成されます。",
        aurora_sec3_desc: "太陽風のB<sub>z</sub>成分が南向き、つまり負になると、条件によっては地球磁場との<strong>磁気リコネクション</strong>が起こりやすくなります。エネルギーや粒子の輸送は増えますが、磁気圏が消えるわけでも、プラズマが単純に直進して内部へ入るわけでもありません。",
        aurora_sec4_desc: "太陽風から移されたエネルギーは<strong>磁気尾</strong>に蓄積することがあります。負のB<sub>z</sub>は通常エネルギー流入を増やしますが、応答はB<sub>z</sub>だけでは決まりません。磁気尾でのエネルギー放出は粒子を極へ導き、オーロラ帯の拡大と明るさに寄与します。",
        aurora_sec5_desc: "極域へ向かう高エネルギー粒子は大気中の原子や分子を励起し、低いエネルギー状態へ戻る際に光を放ちます。<br><br>• <b>緑:</b> 約100～150 kmでは励起された原子状酸素の放射が目立ちます。<br><br>• <b>赤:</b> 高高度の希薄な原子状酸素と特に関係します。窒素や窒素分子イオンも青、紫、赤みのある色に寄与します。色だけで嵐の強さを決めることはできません。",
        qs_info_observer_desc: "<span class=\"danger-text\">検出器</span>がどちらのスリットを通ったかという情報を得ると、2つの経路の量子コヒーレンスが低下し、干渉パターンが消えることがあります。意識的な観測者は必要なく、検出器との物理的相互作用で十分です。粒子は古典的な球になるのではなく、量子法則に従い続けます。",
        bh_sec3_desc: "シュヴァルツシルト・ブラックホールでは、中心から <code>1.5 × rₛ</code> の距離がフォトン球の半径です。そこでの光の軌道は不安定で、非常に正確な方向なら短時間周回できますが、わずかな違いで脱出または落下します。これは事象の地平面ではありません。"
    },
    en: {
        sir_isolation_info: "<strong>🏠 Model isolation:</strong> Infected individuals stay home according to the selected rate; in the simulation this reduces transmission probability, but real-world isolation may not eliminate transmission completely.",
        sir_recovered_info: "<strong>■ Recovered (Green):</strong> Individuals who do not become reinfected in the simulation; this represents the model's immunity assumption.",
        dp_card1_desc: "As the first arm swings down, energy is transferred through the joint to the second arm; it is not transferred entirely, but shared between both arms' motions. This nonlinear transfer can make the second arm reach very large angular speeds.",
        dp_card2_title: "Chaotic Motion (Apparent Trail Crossings)",
        dp_card2_desc: "The trails may overlap on screen. If the complete physical state returns to the same position and velocities, the motion is periodic; this is possible for special initial conditions. In chaotic motion, small initial differences grow and make long-term prediction difficult.",
        lz_butterfly_desc: "<strong>\"A butterfly flapping its wings in Brazil can cause a tornado in Texas.\"</strong> This is a metaphor for how small initial differences can grow in chaotic systems, not a direct law of causation. The two-winged geometry of the Lorenz system is called a <strong>strange attractor</strong>. Its trajectory does not intersect itself in three-dimensional phase space; apparent crossings in a 2D drawing can result from projection.",
        aurora_sec2_desc: "Earth's magnetic field is generated mainly by the geodynamo: motion of conducting fluid in the outer core. It creates the magnetosphere, which acts as a protective region against charged solar plasma. When the solar wind arrives at supersonic speed, a <b>bow shock</b> forms on Earth's sunward side.",
        aurora_sec3_desc: "When the solar-wind B<sub>z</sub> component points south, or negative, conditions can favor magnetic reconnection with Earth's field. This can increase energy and particle transfer, but the magnetosphere does not disappear and the plasma does not simply flow straight inside.",
        aurora_sec4_desc: "Energy transferred from the solar wind can accumulate in the <b>magnetotail</b>. Negative B<sub>z</sub> generally increases energy input, but the response depends on more than B<sub>z</sub> alone. Energy releases in the tail can direct particles toward the poles, contributing to an expanded auroral oval and brighter aurora.",
        qs_info_observer_desc: "When a <span class=\"danger-text\">detector</span> obtains which-path information, coherence between the two paths can be reduced and the interference pattern may disappear. No conscious observer is required; physical interaction with the detector is enough. The particles do not become classical billiard balls: they still obey quantum laws.",
        bh_sec3_desc: "For a Schwarzschild black hole, <code>1.5 × rₛ</code> from the center is the radius of the photon sphere. Light orbits there are unstable: at a very precise direction light may circle briefly, while a small difference can make it escape or fall inward. This is not the event horizon.",
        gal_card_dm_desc: "The motion of stars in the outer parts of galaxies differs from what visible matter alone predicts. Observations point to the additional gravitational effect of dark matter, which interacts very weakly with light. The control shows this model effect; dark matter is not directly observed as a literal shield or glue.",
        ig_formula_pressure: "Impulse transferred to a wall is approximately 2 × mass × the velocity component normal to the wall for an elastic collision.<br>Real impulse = single-particle impulse × 10²²<br>Force (F) = total impulse / elapsed time<br>Pressure (P) = force (F) / surface area",
        ig_intro: "This simulation uses SI units to illustrate an ideal-gas model. Screen particles represent groups of real molecules through a chosen scale factor; the goal is to show how macroscopic gas laws emerge from microscopic motion and wall collisions.",
        ig_scaling_text: "A real container contains an enormous number of molecules. Each screen ball therefore represents many molecules using a chosen scale factor. That factor is a modeling choice, not a constant of nature.",
        se_legend_singularity: "⚛️ Singularity (limit of the classical model)",
        se_desc_supernova: "Fusion in an iron core no longer provides energy, so the core can collapse. Different types of core-collapse supernovae can result depending on whether the hydrogen envelope remains; this model shows a Type II example.",
        se_desc_neutron: "During core collapse, electron capture makes the matter neutron-rich. Neutron stars are about 20 km across and can have very strong magnetic fields; some emit radiation beams or jets from their poles.",
        ks_fact_current: "The estimate K ≈ 0.73 for humanity's Kardashev level depends on the chosen energy definition; it is not a universally accepted precise measurement. We do not know when Type I would be reached.",
        ks_fact_type1: "Kardashev Type I describes a hypothetical civilization able to use energy on a planetary scale. Full control of climate and geology, fusion power, and space elevators are speculative interpretations, not required parts of the scale.",
        ks_fact_type2: "Type II describes a hypothetical civilization using energy on the scale of its star. A Dyson sphere is not required; a partial Dyson swarm is a more practical example. Using all energy without loss is an idealized assumption.",
        ks_fact_type3: "Type III is a speculative class for galactic-scale energy use. Ideas such as extracting energy from black holes do not automatically violate physics, but bending spacetime or surpassing physical laws is not an established consequence of the scale."
    }
};

// These locale-specific sets are declared with the English block above and applied after all locales load.
