    aurora_sec1_desc: "El Sol expulsa plasma cargado al espacio a velocidades supersónicas. Este plasma transporta consigo el campo magnético solar, conocido como <b>campo magnético interplanetario (IMF)</b>. <b>B<sub>z</sub></b> representa la orientación norte-sur (eje Z) de este campo al llegar a la Tierra.",
