    drake_filter_diag_low: "<strong>Der Große Filter liegt hinter uns:</strong> Die Entstehung von Leben und Intelligenz ist äußerst selten. Die Menschheit könnte den schwierigsten Teil des Filters bereits überwunden haben.",
    drake_filter_diag_mid: "<strong>Der Große Filter liegt vor uns:</strong> Biologische Intelligenz ist verbreitet, aber die Lebensdauer von Zivilisationen (L) ist kurz. Zivilisationen sind dem Risiko technologischer Selbstzerstörung ausgesetzt.",
    drake_filter_diag_high: "<strong>Zeitalter der kosmischen Kommunikation:</strong> Die Hindernisse des Filters sind überwindbar. Unsere Galaxie ist voller gleichzeitig existierender technologischer Zivilisationen.",
