    drake_info_r_title: "Sternentstehungsrate (R*)",
    drake_info_r_body: "Die Rate, mit der in unserer Galaxie pro Jahr Sterne entstehen. Durch moderne Beobachtungen sehr gut eingeschränkt. Ungefähr <strong>2 Sterne/Jahr</strong>.",
    drake_info_fp_title: "Anteil der Sterne mit Planeten (fp)",
    drake_info_fp_body: "Der Anteil der Sterne mit mindestens einem Planeten. Daten des Kepler-Weltraumteleskops zufolge besitzen fast alle Sterne Planeten: ungefähr <strong>100 % (1,0)</strong>.",
    drake_info_ne_title: "Anzahl bewohnbarer Planeten (ne)",
    drake_info_ne_body: "Die durchschnittliche Anzahl von Planeten pro Sternsystem, die in der bewohnbaren Zone Leben ermöglichen könnten. Die Schätzungen reichen von <strong>0,1 bis 5,0</strong>.",
    drake_info_fl_title: "Anteil der Planeten mit Leben (fl)",
    drake_info_fl_body: "Die Wahrscheinlichkeit, dass auf einem bewohnbaren Planeten Leben entsteht. Sie ist äußerst unsicher: pessimistisch <strong>0,1 %</strong>, optimistisch bis zu <strong>100 %</strong>.",
    drake_info_fi_title: "Anteil mit entstehender Intelligenz (fi)",
    drake_info_fi_body: "Die Wahrscheinlichkeit, dass sich nach der Entstehung von Leben intelligentes oder bewusstes Leben entwickelt. Meist wird sie auf <strong>1–50 %</strong> geschätzt.",
    drake_info_fc_title: "Anteil mit Technologie (fc)",
    drake_info_fc_body: "Die Wahrscheinlichkeit, dass intelligente Arten Technologien für die Radiokommunikation entwickeln. Sie wird auf <strong>1–50 %</strong> geschätzt.",
    drake_info_l_title: "Nachweisbare Lebensdauer (L)",
    drake_info_l_body: "Wie lange eine Zivilisation aktiv bleibt und nachweisbare Radiosignale aussendet. Der spekulativste Faktor, geschätzt auf <strong>100 Jahre bis 10 Millionen Jahre</strong>.",
    drake_info_earth_title: "Erdvergleich",
    drake_info_earth_body: "Die <strong>Erde</strong> existiert seit 4,5 Milliarden Jahren, Leben seit 3,8 Milliarden Jahren, Homo sapiens seit etwa 300.000 Jahren und eine <strong>Radiotechnik-Zivilisation seit etwa 100 Jahren.</strong> Wenn die Erde durchschnittlich ist, könnte L zwischen 100 und 500.000 Jahren liegen. Mit dieser Annahme ergibt das mittlere Szenario der Drake-Gleichung etwa <strong>2.000 Zivilisationen</strong>.",
    drake_filter_balanced_title: "<strong>Zeitalter der kosmischen Kommunikation:</strong>",
    drake_filter_balanced_desc: "Die Hindernisse des Filters sind überwindbar. Unsere Galaxie ist voller gleichzeitig existierender technologisch fortgeschrittener Zivilisationen.",
    drake_filter_behind_badge: "FILTER HINTER UNS",
    drake_filter_balanced_badge: "AUSGEGLICHENES UNIVERSUM",
    drake_info_seti_title: "SETI und kosmisches Wasserloch (Water Hole)",
    drake_info_seti_body: "SETI (Suche nach extraterrestrischer Intelligenz) sucht im Frequenzband von 1.420–1.666 GHz nach künstlichen Signalen. Dieser Bereich liegt zwischen den Emissionslinien von Wasserstoff (1.420 GHz) und Hydroxyl (1.666 GHz), also H + OH = H₂O, und gilt als besonders ruhiger Kanal für interstellare Kommunikation.",
