    seti_von_fact_title: "Wie funktioniert es? (Entfernungs- und Zeitmodell)",
    seti_von_fact_desc: "Jedes Kolonisierungsereignis wird anhand der Entfernung zwischen den Sternen geteilt durch die Sondengeschwindigkeit plus 50 Jahre Produktionszeit geplant. Die Sterne bilden eine repräsentative Scheibe mit einem Durchmesser von 200 Lichtjahren, daher ist dies keine Vorhersage für die reale Galaxie.",
