    seti_dark_fact_desc: "Signale bewegen sich mit Lichtgeschwindigkeit, Geschosse dagegen mit 0,97c. Daher erreicht das Signal sein Ziel zuerst. Die Zerstörungswahrscheinlichkeit ist kein beobachteter Wert, sondern ein Modellparameter zur Untersuchung der Hypothese des dunklen Waldes.",
