    seti_swarm_count: "Anzahl der Schwarmobjekte:",
    seti_dyson_fact_title: "Wie funktioniert es? (Thermodynamischer IR-Überschuss)",
    seti_dyson_fact_desc: "Die Verdeckung wird aus der gesamten geometrischen Fläche der Panels vor der Sternscheibe berechnet. Der IR-Wert ist eine normalisierte Schätzung des eingefangenen Sternenlichts. Für einen realen Dyson-Schwarm müssten außerdem Panelgröße, Umlaufradius, Temperatur und Emissionsspektrum berücksichtigt werden.",
