    seti_collectors_placed: "{count} Solarkollektoren wurden um den Stern platziert.",
    seti_no_broadcast: "Keine schweigende Zivilisation ist mehr zum Senden übrig.",
    seti_new_system: "Ein neues System ist dem Netzwerk beigetreten. Die Gesamtkapazität der Sonden steigt.",
