    seti_threat_detected: "Bedrohung entdeckt! CIV-{source} hat ein Geschoss mit 0,97c auf CIV-{target} abgefeuert.",
    seti_civ_destroyed: "CIV-{id} wurde zerstört. Die Aussendung wurde dauerhaft unterbrochen.",
    seti_transit: "Transitbeobachtung: Das Sternenlicht nahm um %{drop} ab.",
    seti_report_von_title: "Von-Neumann-Kolonisierung",
    seti_report_von_summary: "<strong>Was ist das?</strong> Ein Gedankenexperiment darüber, wie sich eine Zivilisation mithilfe selbstreplizierender Raumfahrzeuge von Stern zu Stern ausbreiten könnte.",
    seti_report_von_explanation: "<strong>Was siehst du?</strong> Blaue Punkte zeigen erreichte Sternsysteme, Ringe die Ankunft einer Sonde in einem neuen System. Eine höhere Sondengeschwindigkeit erleichtert das Erreichen ferner Systeme, aber jedes neue System benötigt 50 Jahre für die Produktion einer Sonde.",
    seti_report_von_note: "<strong>Wie ist das Ergebnis zu lesen?</strong> Dies ist nicht die tatsächliche Kolonisierungszeit der Milchstraße. Das Modell zeigt, wie Lichtjahre, Geschwindigkeit und Produktionszeit das Ergebnis beeinflussen.",
    seti_report_dark_title: "Dunkler Wald",
    seti_report_dark_summary: "<strong>Was ist das?</strong> Ein spieltheoretisches Szenario, das untersucht, ob eine Zivilisation durch ihre Aussendung sichtbar und dadurch zu einem Ziel werden könnte.",
    seti_report_dark_explanation: "<strong>Was siehst du?</strong> Die gelbe Welle ist ein Funksignal, das sich mit Lichtgeschwindigkeit ausbreitet. Die pinke Linie zeigt einen langsameren Angriff. Eine Zivilisation könnte antworten, wenn sie das Signal stark genug erkennt.",
    seti_report_dark_note: "<strong>Wie ist das Ergebnis zu lesen?</strong> Die Antwortwahrscheinlichkeit ist keine Beobachtung. Sendeleistung, Bandbreite und Empfängertemperatur bestimmen, ob das Signal nachweisbar ist; die Antwort-Einstellung bestimmt, was danach geschieht.",
    seti_report_dyson_title: "Dyson-Schwarm und Lichtkurve",
    seti_report_dyson_summary: "<strong>Was ist das?</strong> Eine Darstellung, wie eine Zivilisation, die Energie um ihren Stern sammelt, aus großer Entfernung aussehen könnte.",
    seti_report_dyson_explanation: "<strong>Warum nimmt das Licht nur um wenige Prozent ab?</strong> Die Panels ziehen nicht alle gleichzeitig vor dem Stern vorbei, und jedes Panel bedeckt nur einen kleinen Teil der Sternscheibe. Ein Rückgang um wenige Prozentpunkte ist bei diesen Einstellungen normal.",
    seti_report_dyson_note: "<strong>Warum ist der IR-Wert so klein?</strong> Die Panels fangen nur einen kleinen Teil des gesamten Sternenlichts ein. Dies ist eine normalisierte Schätzung der eingefangenen Energie und kein echtes Infrarotspektrum.",

