    sir_isolation_info: "<strong>🏠 Realistische Isolation:</strong> Erkrankte Personen bleiben entsprechend der gewählten Isolationsrate zu Hause und übertragen das Virus nicht weiter.",
    sir_transmission_info: "<strong>🎯 Kontaktrisiko:</strong> Die Ansteckungswahrscheinlichkeit bei engem Kontakt wird an die Kontaktdauer angepasst. Dies ist ein Modell mit beweglichen Agenten und kein klassisches homogenes SIR-Modell.",
