    // --- SIMULATION PAGE: AURORA (NORTHERN LIGHTS) ---
    aurora_page_title: "Sonne, IMF B<sub>z</sub> und Magnetotail-Aurora-Simulation",
    aurora_panel_toggle_hide: "Panel ausblenden",
    aurora_panel_toggle_show: "Panel öffnen",
    aurora_info_toggle_guide: "Aurora-Leitfaden",
    aurora_info_toggle_close: "Schließen",
    aurora_panel_title: "Aurora-Physik der Sonne und des IMF B<sub>z</sub>",
    aurora_panel_desc: "3D-Modell der magnetischen Rekonnexion und des Weltraumwetters.",
    aurora_lbl_speed: "Geschwindigkeit des Sonnenwinds (v)",
    aurora_lbl_bz: "IMF B<sub>z</sub> (Polarität)",
    aurora_lbl_count: "Teilchendichte",
    aurora_lbl_field: "Magnetische Feldlinien",
    aurora_lbl_shock: "Stoßwelle und Schweif",
    aurora_tele_reconn: "Rekonnexion:",
    aurora_reconn_active: "Aktiv (südwärts)",
    aurora_reconn_inactive: "Inaktiv (nordwärts)",
    aurora_tele_power: "Auroraler Leistungsindex:",
    aurora_btn_reset_cam: "Kamera zurücksetzen",
    aurora_legend_shock: "Bugstoßwelle",
    aurora_legend_tail: "Magnetotail-Plasmaschweif",
    aurora_legend_storm: "Emission eines starken Sturms (Rot / Rosa)",
    aurora_info_main_title: "Physik der Aurora und der Magnetosphäre",
    aurora_sec1_title: "1. Was sind Sonnenwind und IMF B<sub>z</sub>?",
    aurora_sec1_desc: "Die Sonne schleudert geladene Plasmen mit Überschallgeschwindigkeit ins All. Dieses Plasma zieht das Magnetfeld der Sonne mit sich. Es wird als <b>interplanetares Magnetfeld (IMF)</b> bezeichnet. <b>B<sub>z</sub></b> beschreibt die Nord-Süd-Ausrichtung (Z-Achse) dieses Magnetfelds, wenn es die Erde erreicht.",
    aurora_sec2_title: "2. Magnetischer Schutz und Bugstoßwelle",
    aurora_sec2_desc: "Die Magnetosphäre der Erde wirkt wie ein gewaltiger unsichtbarer Schutzschild gegen geladenes Sonnenplasma. Wenn der mit 400–1000 km/s herannahende Sonnenwind auf diesen Schild trifft, wird er abrupt abgebremst. Ähnlich wie ein Überschallflugzeug die Luft vor sich verdichtet, erzeugt er vor der Erde eine helle gelbe <b>Bugstoßwelle</b>.",
    aurora_sec3_title: "3. Warum entstehen bei negativem B<sub>z</sub> Stürme?",
    aurora_sec3_desc: "Das Magnetfeld der sonnenzugewandten Erdseite zeigt immer nach <b>Norden</b>. Zeigt die ankommende B<sub>z</sub>-Komponente nach <b>Süden (negativ)</b>, ziehen sich entgegengesetzte Pole an. Die Magnetfelder verbinden und lösen sich neu; dieser Vorgang heißt <b>magnetische Rekonnexion</b>. Dadurch entsteht sozusagen eine offene Tür im Schutzschild der Erde, durch die geladenes Sonnenplasma direkt in unser System eindringen kann.",
    aurora_sec4_title: "4. Warum werden Polarlichter intensiver?",
    aurora_sec4_desc: "Das eindringende Plasma wird in den rückwärtigen, im Sonnenwind flatternden Teil des Schutzschilds, den <b>Magnetotail</b>, gezogen. Je negativer B<sub>z</sub> wird (z. B. -15 nT), desto mehr Energie dringt ein und sammelt sich im Schweif. Schließlich wird diese Energie wie aus einer gewaltigen elektromagnetischen Schleuder (Lorentzkraft) freigesetzt und beschleunigt Millionen geladener Teilchen zu den Erdpolen. Mit zunehmender Sturmstärke steigen Anzahl und Energie der in die Atmosphäre eindringenden Elektronen, wodurch sich das Polarlichtoval ausdehnt und die Lichter heller werden.",
    aurora_sec5_title: "💡 Atmosphärische Kollisionen und Farben",
    aurora_sec5_desc: "Elektronen, die mit unglaublicher Geschwindigkeit zu den Polen geschleudert werden, stoßen mit Gasmolekülen der Atmosphäre zusammen und regen diese zur Emission von Photonen an:<br><br>• <b>Grün / Cyan:</b> Entsteht durch Kollisionen mit Sauerstoffatomen (O) in einer Höhe von etwa 100–150 km.<br><br>• <b>Rot / Rosa:</b> Bei starken geomagnetischen Stürmen (hohe Sonnenwindgeschwindigkeit, stark negatives B<sub>z</sub>) dringen energiereiche Elektronen tiefer ein oder regen seltenen Sauerstoff in großer Höhe (über 300 km) und dichte Stickstoffmoleküle (N<sub>2</sub>) in geringer Höhe (unter 100 km) an. Rote Emissionen bei stark negativem B<sub>z</sub> weisen auf einen energiereichen Sturm hin.",

    // --- SIMULATION PAGE: IDEAL GAS EQUATION ---
    ig_page_title: "LAB-PV | Labor für ideale Gase und kinetische Theorie",
    ig_back: "Zum Hauptbildschirm",
    ig_title: "Labor für ideale Gase und kinetische Theorie",
    ig_subtitle: "Präziser Thermodynamik-Simulator mit SI-Einheiten",
    ig_read_explanation: "Wissenschaftliche Erklärung lesen",
    ig_formula_constants: "k_B = 1.380649 × 10⁻²³ J/K (Boltzmann-Konstante - Verbindung zwischen Temperatur und Energie)<br>N_A = 6.02214076 × 10²³ mol⁻¹ (Avogadro-Konstante - Anzahl der Teilchen in einem Mol)<br>R = k_B · N_A = 8.314 J/(mol·K) (universelle Gaskonstante)<br>1 atm = 101.325 Pa (Standarddruck auf Meereshöhe)",
    ig_formula_scaling: "1 simulierte Kugel = 1,00 × 10²² reale Moleküle<br>Gesamtzahl realer Moleküle (N_real) = Anzahl der Kugeln auf dem Bildschirm × 10²²<br>Stoffmenge (mol) = Gesamtzahl realer Moleküle / Avogadro-Konstante",
    ig_formula_pressure: "Impuls eines Teilchens = 2 × Masse × Geschwindigkeit<br>Realer Impuls = Impuls eines Teilchens × 10²²<br>Kraft (F) = Summe aller Impulse / vergangene Zeit<br>Druck (P) = Kraft (F) / gesamte Oberfläche des Behälters",
    ig_formula_distribution: "v_mp: Geschwindigkeit der meisten Teilchen ( wahrscheinlichste Geschwindigkeit)<br>v_avg: durchschnittliche Geschwindigkeit aller Teilchen<br>v_rms: in physikalischen Formeln verwendete quadratische Mittelgeschwindigkeit (Grundlage der Energieberechnung)",
    ig_formula_title: "THERMODYNAMISCHE ZUSTANDSGLEICHUNG",
