    ig_section_constants: "1. Grundlegende Konstanten des Universums",
    ig_section_scaling: "2. Prinzip der Teilchengruppierung (Grobe Skalierung)",
    ig_section_pressure: "3. Was ist Druck wirklich? (Impuls und Kollisionen)",
    ig_section_distribution: "4. Molekülbewegung (Geschwindigkeitsverteilung)",
    ig_intro: "Diese Simulation arbeitet ohne künstliche Koeffizienten vollständig mit universellen SI-Einheiten. Sie zeigt, wie makroskopische Gasgesetze aus der Bewegung mikroskopischer Teilchen und deren Kollisionen mit den Wänden entstehen.",
    ig_constants_intro: "Die Simulation verwendet die unveränderlichen Naturkonstanten aus den Physiklehrbüchern:",
    ig_scaling_text: "Selbst ein winziger Behälter enthält Moleküle in der Größenordnung von 10²³. Daher repräsentiert jede Kugel auf dem Bildschirm eine Gruppe von 10²² Molekülen. Die Naturgesetze gelten für diese Gruppen mit derselben Genauigkeit.",
    ig_pressure_text: "Druck ist keine unsichtbare magische Kraft, sondern das Ergebnis unzähliger Teilchen, die ständig mit den Wänden zusammenstoßen und von ihnen abprallen. Die Simulation berechnet den Impuls jedes Aufpralls. Die Summe dieser kleinen Stöße ergibt den Druckwert.",
    ig_distribution_text: "Die Gasmoleküle in einem Behälter bewegen sich nicht alle mit derselben Geschwindigkeit. Einige sind langsam, andere schnell, die meisten bewegen sich mit einer mittleren Geschwindigkeit. Bei steigender Temperatur wird Energie auf die Moleküle übertragen und diese Bewegung beschleunigt. Diese Verteilung wird Maxwell-Boltzmann-Geschwindigkeitsverteilung genannt.",
    ig_confirm_title: "Zum Hauptbildschirm zurückkehren",
    ig_confirm_text: "Möchtest du die Simulation wirklich beenden und zum Hauptbildschirm zurückkehren?",
