    ig_fact_current: "Die Menschheit befindet sich derzeit auf der Stufe Typ 0. Unsere Energie stammt größtenteils aus fossilen Brennstoffen und der Kernspaltung. Bis Typ 1 sind es vermutlich noch etwa 100–200 Jahre.",
