    rel_fact_low: "<b>Klassische Physik:</b> Deine Geschwindigkeit ist sehr niedrig, daher ist der Effekt der Zeitdilatation praktisch nicht wahrnehmbar. Du alterst genauso schnell wie auf der Erde.",
    rel_fact_mid: "<b>Deutliche Zeitverschiebung:</b> Du reist mit {speed}% der Lichtgeschwindigkeit. Während auf deinem Schiff <b>{shipTime}</b> vergehen, sind für deine Angehörigen auf der Erde <b>{earthTime}</b> vergangen.",
