    ss_kepler_proven: "Nachgewiesen",
    ss_desc_mercury: "Merkur besitzt kaum eine Atmosphäre. Durch den Sonnenwind, der auf seine Oberfläche trifft, enthält er nur Spuren einzelner Elemente.",
    ss_desc_venus: "Venus besitzt eine extrem dichte und dicke Atmosphäre. Ihr starker Treibhauseffekt erzeugt Wolken aus Schwefelsäure.",
    ss_desc_earth: "Die Erde besitzt ein einzigartiges Gasgleichgewicht, das Leben ermöglicht. Ihre Atmosphäre enthält 78 % Stickstoff und 21 % Sauerstoff.",
    ss_desc_mars: "Die dünne Atmosphäre des Roten Planeten besteht zu 95,3 % aus Kohlendioxid. Eisenoxidstaub auf seiner Oberfläche verleiht ihm seine rostige Farbe.",
    ss_desc_jupiter: "Jupiter besitzt als riesiger Gasplanet keine feste Oberfläche. Er besteht hauptsächlich aus molekularem Wasserstoff und Helium.",
    ss_desc_saturn: "Der Ringplanet besteht ähnlich wie Jupiter überwiegend aus Wasserstoff und Helium.",
    ss_desc_uranus: "Uranus ist ein geneigter Eisriese. In seinen kalten Tiefen befindet sich Methan, das ihm seine blaugrüne Farbe verleiht.",
    ss_desc_neptune: "Neptun ist der windreichste Eisriese des Systems und beherbergt die stärksten Winde im Sonnensystem.",

    // --- SIMULATION PAGE: IDEAL GAS EQUATION / PAGE DE SIMULATION : ÉQUATION DES GAZ PARFAITS ---
    ig_page_title: "LAB-PV | Laboratoire des gaz parfaits et de la théorie cinétique",
    ig_back: "Retour à l'écran principal",
    ig_title: "Laboratoire des gaz parfaits et de la théorie cinétique",
    ig_subtitle: "Simulateur thermodynamique de précision avec unités SI",
    ig_read_explanation: "Lire l'explication scientifique",
    ig_formula_constants: "k_B = 1.380649 × 10⁻²³ J/K (constante de Boltzmann - lien entre température et énergie)<br>N_A = 6.02214076 × 10²³ mol⁻¹ (constante d'Avogadro - nombre de particules dans une mole)<br>R = k_B · N_A = 8.314 J/(mol·K) (constante des gaz parfaits)<br>1 atm = 101 325 Pa (pression atmosphérique standard au niveau de la mer)",
    ig_formula_scaling: "1 bille simulée = 1,00 × 10²² molécules réelles<br>Nombre total de molécules réelles (N_real) = nombre de billes à l'écran × 10²²<br>Quantité de matière (mol) = nombre total de molécules réelles / constante d'Avogadro",
    ig_formula_pressure: "Impulsion d'une particule = 2 × masse × vitesse<br>Impulsion réelle = impulsion d'une particule × 10²²<br>Force (F) = somme de toutes les impulsions / temps écoulé<br>Pression (P) = force (F) / surface totale du récipient",
    ig_formula_distribution: "v_mp : vitesse la plus probable<br>v_avg : vitesse moyenne de toutes les particules<br>v_rms : vitesse quadratique moyenne utilisée dans les formules physiques",
