    ig_section_constants: "1. Constantes fondamentales de l'Univers",
    ig_section_scaling: "2. Principe du regroupement des particules (échelle approximative)",
    ig_section_pressure: "3. Qu'est-ce que la pression ? (Impulsion et collisions)",
    ig_section_distribution: "4. Mouvement moléculaire (distribution des vitesses)",
    ig_intro: "Cette simulation utilise les unités SI universelles sans coefficients artificiels. Elle montre comment les lois macroscopiques des gaz émergent du mouvement des particules microscopiques et de leurs collisions avec les parois.",
    ig_constants_intro: "La simulation utilise les constantes immuables de la nature présentées dans les manuels de physique :",
    ig_scaling_text: "Même un petit récipient contient de l'ordre de 10²³ molécules. Chaque bille à l'écran représente donc un groupe de 10²² molécules. Les lois de la nature s'appliquent à ces groupes avec la même précision.",
    ig_pressure_text: "La pression n'est pas une force magique invisible ; elle résulte d'innombrables particules qui heurtent continuellement les parois. La somme de ces petits impacts crée la valeur de la pression.",
    ig_distribution_text: "Les molécules de gaz d'un même récipient ne se déplacent pas toutes à la même vitesse. Certaines sont lentes, d'autres rapides, tandis que la plupart se déplacent à une vitesse moyenne. Lorsque la température augmente, les molécules reçoivent de l'énergie et ce mouvement s'accélère. Cette distribution est appelée distribution des vitesses de Maxwell-Boltzmann.",
