    qs_info_duality_title: "Welle-Teilchen-Dualismus",
    qs_info_duality_desc: "In der klassischen Physik verhält sich Licht wie eine Welle. Im <span class=\"highlight-text\">Quantenmodus</span> entsteht jedoch selbst dann, wenn Photonen oder Elektronen einzeln ausgesendet werden, mit der Zeit ein Interferenzmuster, das mit dem Wellenmodell übereinstimmt. Die Wahrscheinlichkeitsamplituden des Teilchens treten durch beide Spalte und erzeugen Interferenz.",
