    qs_info_observer_desc: "Wenn du einen <span class=\"danger-text\">Detektor</span> hinzufügst und misst, durch welchen Spalt das Teilchen gelangt, verschwindet das quantenmechanische Interferenzverhalten. Die Messung lässt die Wellenfunktion kollabieren; die Teilchen verhalten sich wie klassische Billardkugeln und das Interferenzmuster wird durch zwei deutliche Streifen ersetzt.",
