    se_reaction_heavy: "Fusion schwerer Elemente",
    se_reaction_hyper: "Vollständiger Kollaps",
    se_reaction_singularity: "Singularität",
    se_desc_sun_cloud: "Eine kalte, riesige Molekülwolke aus Gas und Staub kollabiert unter ihrer eigenen Gravitation. In ihrem Zentrum bildet sich ein dichter, heißer Protosternkeim.",
    se_desc_sun_main: "Stabile Phase der Wasserstoffverbrennung. Die thermonukleare Fusion im Kern und die Gravitation befinden sich im hydrostatischen Gleichgewicht.",
    se_desc_sun_red: "Der Wasserstoff im Kern ist aufgebraucht. Der Heliumkern zieht sich zusammen und erhitzt sich, während die Wasserstoffbrennschale die äußeren Schichten ausdehnt und abkühlt.",
    se_desc_sun_white: "Die äußeren Schichten werden als planetarischer Nebel ins All abgestoßen. Der verbleibende heiße Kern wird durch den Elektronenentartungsdruck vor dem Kollaps bewahrt.",
    se_desc_massive_cloud: "Aufgrund ihrer großen Masse kollabiert die Gaswolke heftig. Der hohe Druck lässt den Wasserstoff früh und schnell zünden.",
    se_desc_blue_giant: "Ein viel heißerer Stern als sonnenähnliche Sterne, der seinen Brennstoff durch den CNO-Zyklus schnell verbraucht und intensive Strahlung aussendet.",
    se_desc_red_supergiant: "Im Kern bilden sich geschichtete Schalen. Je näher man zum Zentrum kommt, desto schwerere Elemente brennen, bis der Stern sich der Grenze der Eisenproduktion nähert.",
    se_desc_supernova: "Ein Eisenkern kann keine Energie erzeugen, daher gewinnt die Gravitation. Der kollabierende Kern erzeugt eine Supernova vom Typ II.",
    se_desc_neutron: "Protonen und Elektronen verbinden sich zu Neutronen. Dieses etwa 20 km große Objekt kann von seinen Polen energiereiche Strahlungsjets aussenden.",
    se_desc_blue_supergiant: "Dieser Stern ist hunderttausendfach heller als die Sonne und kann seinen Brennstoff innerhalb weniger Millionen Jahre verbrauchen.",
    se_desc_wolf_rayet: "Starke Sternwinde tragen die äußeren Schichten ins All. In dieser Phase ist der Massenverlust des Sterns sehr hoch.",
    se_desc_hypernova: "Der Kernkollaps kann eine außergewöhnlich starke Explosion erzeugen. Einige Modelle sagen Gammablitze von den Polen voraus.",
    se_desc_blackhole: "Wenn der kollabierende Kern den Neutronenentartungsdruck überwindet, kann ein Schwarzes Loch entstehen. Licht und Informationen können seinem Ereignishorizont nicht entkommen.",

