    mc_edu_toggle: "Menü & Erklärungen",
    mc_edu_html: "<b>Statistische Analyse und Standardabweichung</b><br>Der radioaktive Zerfall ist ein zeitkontinuierlicher, stochastischer (zufälliger) Prozess.<br><span class=\"edu-formula\">λ = (ln 2) / t½</span><br><span class=\"highlight-orange\">🔬 Bestimmung der Halbwertszeit & Konfidenzintervall</span><br>Dieses Labor berechnet bei mehreren Experimenten nicht nur den Mittelwert. Es <b>misst die Halbwertszeit jedes einzelnen</b> Experiments unabhängig voneinander, ob du 10, 100 oder 1000 Simulationen ausführst.<br><br>Anschließend werden die Standardabweichung (<b>σ</b>) und das 95-%-Konfidenzintervall berechnet. Wenn du die Anzahl der Experimente (N) erhöhst, kannst du beobachten, wie Standardfehler und Fehlerspanne drastisch sinken und damit die Genauigkeit wissenschaftlicher Daten sichtbar wird.",
