    bh_show: "Anzeigen",
    bh_mass: "Masse des Schwarzen Lochs:",
    bh_mass_tip: "Mit zunehmender Masse wachsen die Gravitationskraft und die Größe des Schattens des Schwarzen Lochs.",
    bh_density: "Lichtbahnen:",
    bh_density_tip: "Die gekrümmten Wege, denen Lichtstrahlen durch den Raum folgen.",
    bh_nebula: "Hintergrund des tiefen Weltraums (Ferne Sterne)",
    bh_disk: "Gasscheibe (Akkretionsscheibe)",
    bh_photon_ring: "Photonenring (Grenze der Lichtfalle)",
    bh_rays: "3D-Lichtstrahlen",
    bh_science_title: "Lichtkrümmung durch Einsteins Relativitätstheorie",
    bh_intro: "Diese Simulation berechnet mithilfe von Einsteins Allgemeiner Relativitätstheorie, wie Licht um ein massereiches Gravitationsobjekt abgelenkt wird.",
    bh_sec1_title: "1. Krümmung der Raumzeit (Schwarzschild-Metrik)",
    bh_sec1_desc: "Ein Schwarzes Loch krümmt das Gewebe der Raumzeit wie einen tiefen Brunnen. Licht versucht immer, sich gerade durch den Raum zu bewegen. Da der durchquerte Raum gekrümmt ist, sieht ein Beobachter von außen, wie sich seine Bahn krümmt.",
    bh_sec2_title: "2. Reale Lichtbahnen (Null-Geodäten)",
    bh_sec2_desc: "Statt einfacher klassischer Näherungen der Gravitationskraft berechnet diese Simulation die vollständig relativistischen Bahnen des Lichts:",
    bh_equation_label: "Gleichung",
    bh_sec2_result: "Diese Gleichung zeigt physikalisch korrekt, wie Licht, das sehr nah am Schwarzen Loch vorbeikommt, es umkreisen und entkommen oder nach innen gezogen werden kann.",
    bh_sec3_title: "3. Was ist der Photonenring? (Gelbe gestrichelte Linie)",
    bh_sec3_desc: "Dies ist die kritische Grenze in einer Entfernung von <code>1.5 × rₛ</code> vom Zentrum des Schwarzen Lochs. Licht, das sich im richtigen Winkel nähert, tritt in eine Umlaufbahn um das Schwarze Loch ein und beginnt, es kreisförmig zu umkreisen.",
    bh_sec4_title: "4. Farb- und Helligkeitsänderungen in der Gasscheibe",
    bh_doppler: "<b>Doppler-Effekt:</b> Gas, das sich mit hoher Geschwindigkeit auf uns zu bewegt, erscheint heller und blauer. Die sich entfernende Seite ist dunkler und röter.",
    bh_redshift: "<b>Gravitationsbedingte Rotverschiebung:</b> Licht, das aus dem starken Gravitationsbrunnen des Schwarzen Lochs zu uns aufsteigt, verliert Energie und verschiebt sich ins Rote.",

