    dp_card2_desc: "即使屏幕上的二维轨迹看起来相互交叠，系统的完整物理状态也<strong>绝不会完全重复自身</strong>。如果系统再次回到完全相同的位置和速度状态，它就会进入周期循环并变得可以预测。",
    dp_card3_title: "确定性混沌",
    dp_card3_desc: "这种运动完全遵循确定的物理规律（重力和牛顿定律），并不是随机的。然而，这些规律具有高度非线性的复杂性，使长期预测变得不可能。",

