    // --- SIMULATION PAGE: WAVE INTERFERENCE ---
    wi_card1_title: "相长干涉（波腹线）",
    wi_card1_desc1: "这是模拟中<strong>最明亮（橙色）</strong>或<strong>最深（深蓝色）</strong>的区域。来自两个不同波源的波峰（或波谷）会在这些点同时相遇。",
    wi_card1_desc2: "就像两个人同时向同一方向推动一样，波在这里叠加并产生<strong>最大振幅</strong>。在测量模式中捕捉到此区域时，会看到路程差是波长的整数倍（$\\Delta L = n\\lambda$）。",
    wi_card2_title: "相消干涉（节点线）",
    wi_card2_desc1: "这是屏幕上静止的<strong>青色（蓝绿色）直线</strong>。一个波的波峰与另一个波的波谷会在这里正面相遇。",
    wi_card2_desc2: "一个波向上推动介质，另一个波以相同力度向下拉动，因此两者在这里<strong>相互抵消（位移为零）</strong>。水面看起来完全静止。此时路程差必须是半整数倍波长：<span class=\"formula\">$\\Delta L = (n + \\frac{1}{2})\\lambda$</span>。降噪耳机正是利用了这一物理原理！",
    wi_card3_title: "中间区域（过渡相位）",
    wi_card3_desc: "既不是完全增强，也不是完全抵消！这是波峰和波谷<strong>部分</strong>重叠的区域。在模拟中，颜色会逐渐过渡，水面轻微波动，但永远达不到最大振幅。",
    wi_card4_title: "什么是相位差？",
    wi_card4_desc1: "尝试调节上方的<strong>相位差</strong>滑块。这会使一个波源相对于另一个波源稍有延迟地产生波，而不是完全同步。",
    wi_card4_desc2: "观察整个对称图案如何随着时序变化向左或向右移动。因为初始时序改变后，波在空间中的碰撞位置也会改变。",

