    tbp_sec1_title: "三体问题",
    tbp_sec1_desc: "在理想条件下，两个天体的运动可以用闭式解析解表示。加入第三个质量后，一般不存在闭式解，运动需要通过数值方法计算。系统仍然是确定性的，但某些初始条件会产生混沌行为；初始位置或速度的微小差异，尤其在长时间尺度上，也可能导致明显不同的轨道。",
    tbp_sec2_title: "引力抛射与边界选项",
    tbp_sec2_desc: "混沌行为意味着对初始条件敏感，并非所有混沌系统都不稳定。三个天体接近时速度可能增加，相互作用可能使其中一个进入非束缚轨道并逃逸；这并非每组初始条件都会发生。无边界选项可观察这种可能性，人工边界选项则加入指向中心的人工力帮助天体保持在视野内。",
    tbp_sec3_title: "8字形轨道与物理实现",
    tbp_sec3_desc: "这是一个特殊的周期性解：三个等质量天体围绕共同质心描绘8字形轨道。该解的存在已由数学证明，但需要精确设置初始位置和速度；现实中的微小偏差、数值误差和外部影响都可能使轨道逐渐偏离理想形状。",

