    bio_org_nucleus_name: "细胞核",
    bio_org_nucleus_desc: "细胞核是储存DNA的控制中心，具有双层膜结构，内部包含核仁和染色质网络。",
    bio_org_mito_name: "线粒体",
    bio_org_mito_desc: "线粒体是细胞的能量（ATP）中心，其玻璃状外膜内可以看到褶皱状的内膜（嵴）。",
    bio_org_er_name: "粗面内质网",
    bio_org_er_desc: "这种环绕细胞核的网状结构负责物质运输。其表面的点状结构是合成蛋白质的核糖体。",
    bio_org_golgi_name: "高尔基体",
    bio_org_golgi_desc: "高尔基体负责生成、加工、包装分泌物，并通过小囊泡将其运送到目标位置。",
    bio_org_lyso_name: "溶酶体",
    bio_org_lyso_desc: "溶酶体负责细胞内消化，含有能够分解衰老细胞器和外来物质的强效酶。",
    bio_org_centro_name: "中心体（中心粒）",
    bio_org_centro_desc: "中心体存在于动物细胞中，在细胞分裂时移向相反两极并形成纺锤丝。",
    bio_toast_rep_success: "复制成功！前导链和后随链（冈崎片段）已合成。",
    bio_toast_synth_success: "翻译完成！多肽链已合成。",
    bio_base_A_name: "腺嘌呤（A）",
    bio_base_A_desc: "一种嘌呤碱基，与胸腺嘧啶形成2个氢键。",
    bio_base_T_name: "胸腺嘧啶（T）",
    bio_base_T_desc: "一种嘧啶碱基，与腺嘌呤形成2个氢键。",
    bio_base_G_name: "鸟嘌呤（G）",
    bio_base_G_desc: "一种嘌呤碱基，与胞嘧啶形成3个氢键。",
    bio_base_C_name: "胞嘧啶（C）",
    bio_base_C_desc: "一种嘧啶碱基，与鸟嘌呤形成3个氢键。",
    bio_aa_met: "甲硫氨酸（起始）",
    bio_aa_val: "缬氨酸",
    bio_aa_phe: "苯丙氨酸",
    bio_aa_pro: "脯氨酸",
    bio_aa_trp: "色氨酸",
    bio_aa_stop: "终止",
    bio_edu_dna_title: "DNA（脱氧核糖核酸）与遗传密码",
    bio_edu_dna_content: "<b>DNA</b>储存遗传信息，并指导生物体的生长、代谢和细胞分裂。<br><br><h4>双螺旋结构</h4>两条反向平行的核苷酸链通过氢键配对，形成右手双螺旋。<br><br><h4>碱基配对</h4>腺嘌呤与胸腺嘧啶形成2个氢键，鸟嘌呤与胞嘧啶形成3个氢键。",
    bio_edu_prot_title: "蛋白质折叠与结构层次",
    bio_edu_prot_content: "<b>蛋白质</b>承担酶催化、细胞结构、运输和免疫等多种功能。<br><br><h4>四个结构层次</h4>一级结构是氨基酸序列；二级结构包括α螺旋和β折叠；三级结构是完整的三维构象；四级结构由多个多肽亚基组装而成。",
    bio_edu_rep_title: "DNA复制（半保留复制）",
    bio_edu_rep_content: "DNA复制发生在细胞分裂前。解旋酶分开双链，RNA引物酶提供起点，DNA聚合酶以5'到3'方向合成新链，连接酶连接冈崎片段。每个子DNA都包含一条旧链和一条新链。",
    bio_edu_synth_title: "中心法则与蛋白质合成",
    bio_edu_synth_content: "遗传信息通常沿<b>DNA ➔ RNA ➔ 蛋白质</b>方向传递。转录在DNA模板上合成mRNA，翻译则由核糖体读取mRNA密码子，并按照顺序连接氨基酸形成多肽链。",
    bio_edu_cell_title: "细胞生物学与细胞器功能",
    bio_edu_cell_content: "细胞是生命体的基本结构和功能单位。细胞膜负责选择性通透，细胞核储存DNA，线粒体产生ATP，内质网和高尔基体参与蛋白质加工运输，溶酶体负责细胞内消化。",
    bio_ui_synth_title: "中心法则",
    bio_ui_synth_dna_mrna: "DNA -> mRNA：",
    bio_ui_synth_transcription: "转录",
    bio_ui_synth_mrna_prot: "mRNA -> 蛋白质：",
    bio_ui_synth_translation: "翻译",
    bio_ui_synth_active_codon: "当前密码子：",
    bio_ui_synth_amino_acid: "氨基酸：",
    bio_btn_start_synth: "开始翻译",
    bio_btn_synth_running: "合成进行中...",
    bio_btn_restart: "重新开始",
    bio_edu_dna_title: "DNA（脱氧核糖核酸）与遗传密码",
    bio_edu_dna_content: "<b>DNA</b>储存遗传信息，并指导生物体的生长、代谢和细胞分裂。<br><br><h4>双螺旋结构</h4>两条反向平行的核苷酸链通过氢键配对，形成右手双螺旋。<br><br><h4>碱基配对</h4>腺嘌呤与胸腺嘧啶形成2个氢键，鸟嘌呤与胞嘧啶形成3个氢键。",
    bio_edu_prot_title: "蛋白质折叠与结构层次",
    bio_edu_prot_content: "<b>蛋白质</b>承担酶催化、细胞结构、运输和免疫等多种功能。<br><br><h4>四个结构层次</h4>一级结构是氨基酸序列；二级结构包括α螺旋和β折叠；三级结构是完整的三维构象；四级结构由多个多肽亚基组装而成。",
    bio_edu_rep_title: "DNA复制（半保留复制）",
    bio_edu_rep_content: "DNA复制发生在细胞分裂前。解旋酶分开双链，RNA引物酶提供起点，DNA聚合酶以5'到3'方向合成新链，连接酶连接冈崎片段。每个子DNA都包含一条旧链和一条新链。",
    bio_edu_synth_title: "中心法则与蛋白质合成",
    bio_edu_synth_content: "遗传信息通常沿<b>DNA ➔ RNA ➔ 蛋白质</b>方向传递。转录在DNA模板上合成mRNA，翻译则由核糖体读取mRNA密码子，并按照顺序连接氨基酸形成多肽链。",
    bio_edu_cell_title: "细胞生物学与细胞器功能",
    bio_edu_cell_content: "细胞是生命体的基本结构和功能单位。细胞膜负责选择性通透，细胞核储存DNA，线粒体产生ATP，内质网和高尔基体参与蛋白质加工运输，溶酶体负责细胞内消化。",

