    se_desc_sun_cloud: "寒冷的巨大分子气体和尘埃云在引力作用下坍缩，中心形成致密而炽热的原恒星种子。",
    se_desc_sun_main: "稳定的氢燃烧阶段。核心热核聚变产生的向外压力与引力处于流体静力学平衡。",
    se_desc_sun_red: "核心氢耗尽后，氦核心收缩并升温，氢壳层燃烧使外层膨胀并冷却。",
    se_desc_sun_white: "外层以行星状星云形式被抛出，剩余的热核心依靠电子简并压避免坍缩。",
    se_desc_massive_cloud: "由于质量很大，气体云强烈坍缩。高压使氢早期且快速地点燃。",
    se_desc_blue_giant: "它比类太阳恒星更热，通过CNO循环快速消耗燃料并发出强烈辐射。",
    se_desc_red_supergiant: "核心中的元素形成分层燃烧壳。越靠近中心，燃烧的元素越重，恒星逐渐接近铁生成阶段。",
    se_desc_supernova: "铁核心无法继续产生能量，因此引力占据优势。坍缩的核心形成II型超新星。",
    se_desc_neutron: "质子和电子结合形成中子。这个天体直径约20 km，可能从两极发射高能辐射喷流。",
    se_desc_blue_supergiant: "它的亮度可达太阳的数十万倍，燃料可能在几百万年内耗尽。",
    se_desc_wolf_rayet: "强烈的恒星风带走外层物质，这一阶段的失质量率非常高。",
    se_desc_hypernova: "核心坍缩可能产生极强爆炸；部分模型预测两极会出现伽马射线暴。",
    se_desc_blackhole: "如果坍缩核心超过中子简并压，可能形成黑洞。进入事件视界的光和信息无法逃出。",

