    gal_card_event_horizon_title: "事件视界与吸积盘",
    gal_card_spaghetti_desc: "当恒星过于接近黑洞时，巨大的潮汐引力会将其拉伸并撕碎，这种现象称为<strong>意大利面化</strong>。恒星气体落入黑洞时会因摩擦强烈升温。屏幕上的白蓝闪光表示恒星最后阶段释放的能量。",
    gal_card_dm_desc: "星系外围的恒星运行速度很快，若只有可见物质，它们本应逃逸到太空。科学家认为看不见的<strong>暗物质</strong>提供了额外引力，使星系保持稳定。调节控制器可以观察这种模型效应。",
    gal_card_event_horizon_desc: "黑洞中心的黑色区域是<strong>事件视界</strong>，光也无法从中逃出的边界。周围明亮的环由被强引力弯曲并绕行的气体和辐射组成。落入黑洞的物质在被吞噬前可能会最后发光。",

