    seti_dark_fact_desc: "信号以光速传播，而抛射物以0.97c传播，因此信号会先到达。摧毁概率不是观测得出的数值，而是用于研究黑暗森林假说的模型参数。",
    seti_dyson_badge: "技术签名：戴森群与光变曲线",
    seti_dyson_fact_title: "它是如何工作的？（热力学红外过量）",
    seti_dyson_fact_desc: "遮挡率根据面板覆盖恒星圆盘的总几何面积计算。红外数值是捕获星光的归一化估计；真实的戴森群还需要考虑面板面积、轨道半径、温度和发射光谱。",
