    seti_transit: "凌日观测：恒星光线下降了%{drop}。",
    seti_report_von_title: "冯·诺伊曼殖民",
    seti_report_von_summary: "<strong>这是什么？</strong>这是一个思想实验，描述文明如何利用能够自我复制的航天器从一颗恒星扩散到另一颗恒星。",
    seti_report_von_explanation: "<strong>你看到了什么？</strong>蓝色点表示已经到达的恒星系统，环形效果表示探测器正在抵达新系统。探测器速度越高，到达遥远系统就越容易，但每个新系统都需要50年才能生产一台探测器。",
    seti_report_von_note: "<strong>应该如何理解结果？</strong>这不是真实的银河系殖民时间，而是展示光年、速度和生产时间如何影响结果的模型。",
    seti_report_dark_title: "黑暗森林",
    seti_report_dark_summary: "<strong>这是什么？</strong>这是一个博弈论场景，用于研究文明通过广播暴露自身后是否会成为目标。",
    seti_report_dark_explanation: "<strong>你看到了什么？</strong>黄色波纹表示以光速传播的无线电信号，粉色线条表示较慢的攻击。如果一个文明能够足够清晰地探测到信号，就可能进行回应。",
    seti_report_dark_note: "<strong>应该如何理解结果？</strong>响应概率不是观测结果。发射功率、带宽和接收机温度决定信号是否可被探测；响应设置则决定探测之后会发生什么。",
    seti_report_dyson_title: "戴森群与光变曲线",
    seti_report_dyson_summary: "<strong>这是什么？</strong>这是对一个文明在恒星周围收集能量时，从远处可能呈现何种景象的可视化。",
    seti_report_dyson_explanation: "<strong>为什么光线只下降了几个百分点？</strong>因为这些面板不会同时经过恒星前方，而且每个面板相对于恒星圆盘的面积都很小。因此，屏幕上下降几个百分点是正常的。",
    seti_report_dyson_note: "<strong>为什么红外数值这么小？</strong>面板只能捕获恒星总光线中的一小部分。这是归一化的捕获能量估计，并不是真实的红外光谱。",
    seti_report_von_summary: "<strong>这是什么？</strong>这是一个思想实验：文明利用能够自我复制的航天器，从一颗恒星扩散到另一颗恒星。",
    seti_report_von_explanation: "<strong>你看到了什么？</strong>蓝点表示已经到达的恒星系统，环形标记表示探测器正在抵达新系统。探测器速度越高，抵达远方系统越容易，但每个新系统仍需要50年制造探测器。",
    seti_report_von_note: "<strong>如何理解结果？</strong>这不是银河系真实的殖民时间，而是展示距离、速度和制造时间如何影响结果的模型。",
    seti_report_dark_summary: "<strong>这是什么？</strong>这是一个博弈论情景，用来研究广播是否会让文明暴露并成为目标。",
    seti_report_dark_explanation: "<strong>你看到了什么？</strong>黄色波表示以光速传播的无线电信号，粉色线表示较慢的攻击。若文明能充分探测信号，就可能做出回应。",
    seti_report_dark_note: "<strong>如何理解结果？</strong>响应概率不是观测结果。发射功率、带宽和接收机温度影响信号是否可探测，响应设置影响后续结果。",
    seti_report_dyson_summary: "<strong>这是什么？</strong>这是一个可视化模型，展示文明在恒星周围部署大量能量收集结构后，远处观察者可能看到的样子。",
    seti_report_dyson_explanation: "<strong>为什么光度只下降几个百分点？</strong>因为面板不会同时经过恒星前方，而且每个面板只遮挡恒星盘的一小部分。",
    seti_report_dyson_note: "<strong>为什么红外值很小？</strong>面板只捕获恒星总光能的一小部分。该数值是归一化的能量估计，不是真实的红外光谱。",


