    wi_card3_desc: "这里既没有完全增强，也没有完全抵消。波峰与波谷部分重叠，颜色逐渐过渡，振幅处于中间状态。",
    wi_card4_desc1: "调整相位差，可以让一个波源相对于另一个波源稍晚产生波，而不是完全同步。",
    wi_card4_desc2: "改变时间关系后，干涉图样会向左或向右移动，因为波相遇的空间位置也随之改变。",

