    ig_subtitle: "使用SI单位的精密热力学模拟器",
    ig_read_explanation: "阅读科学说明",
    ig_formula_constants: "k_B = 1.380649 × 10⁻²³ J/K（玻尔兹曼常数：温度与能量之间的桥梁）<br>N_A = 6.02214076 × 10²³ mol⁻¹（阿伏伽德罗常数：一摩尔物质中的粒子数）<br>R = k_B · N_A = 8.314 J/(mol·K)（理想气体常数）<br>1 atm = 101,325 Pa（海平面标准大气压）",
    ig_formula_scaling: "1个模拟小球 = 1.00 × 10²²个真实分子<br>真实分子总数（N_real）= 屏幕上的小球数量 × 10²²<br>物质的量（mol）= 真实分子总数 / 阿伏伽德罗常数",
    ig_formula_pressure: "单个粒子的冲量 = 2 × 质量 × 速度<br>真实冲量 = 单个粒子的冲量 × 10²²<br>作用力（F）= 所有冲量的总和 / 经过的时间<br>压力（P）= 作用力（F）/ 容器的总表面积",
    ig_formula_distribution: "v_mp：数量最多的粒子群速度（最概然速率）<br>v_avg：所有粒子的平均速度<br>v_rms：物理公式中使用的均方根速度（能量计算的基础）",
