    ig_intro: "本模拟完全使用通用SI单位，不使用人为系数，展示宏观气体定律如何从微观粒子的运动及其与容器壁的碰撞中产生。",
    ig_constants_intro: "模拟使用物理学教材中记录的自然界基本常数：",
    ig_scaling_text: "即使很小的容器中也包含数量级为10²³的分子。因此，屏幕上的每个小球代表一个由10²²个分子组成的粒子群。物理定律同样精确地适用于这些粒子群。",
    ig_pressure_text: "压力并不是看不见的魔法力，而是无数粒子不断撞击并弹离容器壁的结果。模拟会计算每次碰撞施加的动量，这些微小冲量的总和就形成了压力值。",
    ig_distribution_text: "同一容器中的气体分子并不会以相同速度运动。有些分子较慢，有些较快，而大多数以平均速度运动。温度升高会向分子传递能量，使这种运动加快。这种分布称为麦克斯韦-玻尔兹曼速度分布。",
