    seti_report_dark_note: "<strong>¿Cómo se interpreta?</strong> La probabilidad de respuesta no es una observación. La potencia, el ancho de banda y la temperatura del receptor determinan si la señal es detectable; el ajuste de respuesta determina lo que ocurre después.",
