    wi_btn_measure: "Modo de medición (sonda)",
    wi_lbl_wavelength: "Longitud de onda (λ)",
    wi_lbl_amplitude: "Amplitud (potencia)",
    wi_lbl_phase: "Diferencia de fase (Δφ)",
    wi_card1_title: "🌞 Interferencia constructiva (línea antinodal)",
    wi_card1_desc1: "Estas son las zonas <strong>más brillantes (naranjas)</strong> o <strong>más oscuras (azul marino)</strong> de la simulación. Las crestas (o los valles) de las ondas procedentes de dos fuentes diferentes se encuentran simultáneamente en estos puntos.",
    wi_card1_desc2: "Al igual que dos personas empujando a la vez en la misma dirección, las ondas combinan aquí sus fuerzas y crean una <strong>oscilación máxima</strong>. Al captar esta zona en el modo de medición, verás que la diferencia de recorrido es un múltiplo entero de la longitud de onda ($\Delta L = n\lambda$).",
    wi_card2_title: "🌑 Interferencia destructiva (línea nodal)",
    wi_card2_desc1: "Son las <strong>líneas rectas cian (azul verdoso)</strong> y estacionarias que aparecen en la pantalla. La cresta de una onda choca aquí directamente con el valle de la otra.",
    wi_card2_desc2: "Mientras una onda empuja el medio hacia arriba, la otra tira hacia abajo con la misma fuerza, por lo que ambas <strong>se cancelan (desplazamiento cero)</strong>. El agua parece completamente inmóvil. Para alcanzar este estado, la diferencia de recorrido debe ser un múltiplo semientero: <span class=\"formula\">$\\Delta L = (n + \\frac{1}{2})\\lambda$</span>. Los auriculares con cancelación activa de ruido funcionan exactamente según este principio físico.",
    wi_card3_title: "🌗 Zona intermedia (fase de transición)",
    wi_card3_desc: "¡Ni amplificación total ni cancelación completa! Son regiones donde las crestas y los valles se superponen <strong>parcialmente</strong>. En la simulación, los colores pasan gradualmente de uno a otro. El agua forma pequeñas ondas, pero nunca alcanza la amplitud máxima.",
    wi_card4_title: "⏱️ ¿Qué es la diferencia de fase?",
    wi_card4_desc1: "Prueba a ajustar el control de <strong>diferencia de fase</strong> de arriba. Esto hace que una fuente genere ondas con un pequeño retraso respecto a la otra, en lugar de hacerlo perfectamente sincronizada.",
    wi_card4_desc2: "Observa cómo todo el patrón simétrico se desplaza a la izquierda o a la derecha cuando cambia el tiempo. Al modificar la sincronización inicial, también cambian los puntos del espacio donde chocan las ondas.",
    wi_probe_s1: "Distancia S1",
