    ig_pressure_fluctuation: "Fluctuación de la presión a lo largo del tiempo",
    ig_scientific_explanation: "Gas ideal y teoría cinética: explicación científica",
    ig_close: "Cerrar",
    ig_section_constants: "1. Constantes fundamentales del universo",
    ig_section_scaling: "2. Principio de agrupación de partículas (escala aproximada)",
    ig_section_pressure: "3. ¿Qué es realmente la presión? (Impulso y colisiones)",
    ig_section_distribution: "4. Movimiento molecular (distribución de velocidades)",
    ig_intro: "Esta simulación utiliza unidades SI universales sin coeficientes artificiales. Muestra cómo las leyes macroscópicas de los gases surgen del movimiento de partículas microscópicas y de sus colisiones con las paredes.",
    ig_constants_intro: "La simulación utiliza las constantes inmutables de la naturaleza que aparecen en los libros de física:",
    ig_scaling_text: "Incluso un recipiente pequeño contiene del orden de 10²³ moléculas. Por eso, cada bola de la pantalla representa un grupo de 10²² moléculas. Las leyes de la física se aplican a estos grupos con la misma precisión.",
    ig_pressure_text: "La presión no es una fuerza mágica invisible; es el resultado de incontables partículas que chocan continuamente contra las paredes y rebotan en ellas. La simulación calcula el momento aplicado en cada colisión. La suma de estos pequeños impactos produce el valor de la presión.",
    ig_distribution_text: "Las moléculas de gas del mismo recipiente no se mueven todas a la misma velocidad. Algunas son lentas y otras rápidas, mientras que la mayoría se desplaza a una velocidad media. Al aumentar la temperatura, las moléculas reciben energía y este movimiento se acelera. Esta distribución se denomina distribución de velocidades de Maxwell-Boltzmann.",
    ig_confirm_title: "Volver a la pantalla principal",
    ig_confirm_text: "¿Seguro que quieres salir de la simulación y volver a la pantalla principal?",
