    ks_fact_current: "La humanidad se encuentra actualmente en la etapa de Tipo 0. Obtenemos la mayor parte de nuestra energía de combustibles fósiles y fisión nuclear. Podríamos estar a unos 100-200 años de alcanzar el Tipo 1.",
    ks_fact_type0: "No puede utilizar toda la energía solar que llega a su planeta ni controlar por completo los fenómenos geológicos y atmosféricos.",
    ks_fact_type1: "Puede controlar toda la energía que llega a su planeta, además de su clima y geología. La energía de fusión y los ascensores espaciales serían tecnologías habituales.",
