    bio_btn_org_reset: " Vista general",
    bio_org_nucleus_name: "Núcleo (nucleolo)",
    bio_org_nucleus_desc: "Es el centro de control que contiene el ADN. Está rodeado por una doble membrana y alberga el nucleolo y la red de cromatina.",
    bio_org_mito_name: "Mitocondria",
    bio_org_mito_desc: "Es la central energética de la célula y produce ATP. En su membrana externa se distingue la membrana interna plegada, o crestas.",
    bio_org_er_name: "Retículo endoplasmático rugoso",
    bio_org_er_desc: "Esta red que rodea el núcleo transporta sustancias. Los puntos de su superficie son ribosomas que sintetizan proteínas.",
    bio_org_golgi_name: "Aparato de Golgi",
    bio_org_golgi_desc: "Produce, procesa, empaqueta en pequeñas vesículas y distribuye las sustancias de secreción.",
    bio_org_lyso_name: "Lisosoma",
    bio_org_lyso_desc: "Se encarga de la digestión intracelular. Contiene enzimas que degradan orgánulos envejecidos y sustancias incorporadas desde el exterior.",
    bio_org_centro_name: "Centrosoma (centríolos)",
    bio_org_centro_desc: "Está presente en las células animales. Durante la división celular se desplaza hacia polos opuestos y forma las fibras del huso.",
    bio_toast_rep_success: "¡Replicación completada! Se sintetizaron las cadenas líder y rezagada (Okazaki).",
    bio_toast_synth_success: "¡Traducción completada! Se sintetizó la cadena polipeptídica.",
    bio_base_A_name: "Adenina (A)",
    bio_base_A_desc: "Es una base púrica. Forma 2 enlaces de hidrógeno con la timina.",
    bio_base_T_name: "Timina (T)",
    bio_base_T_desc: "Es una base pirimidínica. Forma 2 enlaces de hidrógeno con la adenina.",
    bio_base_G_name: "Guanina (G)",
    bio_base_G_desc: "Es una base púrica. Forma 3 enlaces de hidrógeno con la citosina.",
    bio_base_C_name: "Citosina (C)",
    bio_base_C_desc: "Es una base pirimidínica. Forma 3 enlaces de hidrógeno con la guanina.",
    bio_aa_met: "Metionina (Inicio)",
    bio_aa_val: "Valina",
    bio_aa_phe: "Fenilalanina",
    bio_aa_pro: "Prolina",
    bio_aa_trp: "Triptófano",
    bio_aa_stop: "Alto",
    bio_edu_dna_title: " ADN (ácido desoxirribonucleico) y código genético",
    bio_edu_dna_content: "El <b>ADN</b> almacena la información hereditaria y dirige el crecimiento, el metabolismo y la división celular. <br><br><h4>Estructura de doble hélice</h4>Dos cadenas de nucleótidos antiparalelas se unen mediante enlaces de hidrógeno y forman una doble hélice dextrógira.<br><br><h4>Reglas de apareamiento</h4>La adenina y la timina forman 2 enlaces de hidrógeno, mientras que la guanina y la citosina forman 3.",
    bio_edu_prot_title: "Plegamiento de proteínas y niveles estructurales",
    bio_edu_prot_content: "Las <b>proteínas</b> son máquinas moleculares que participan en la catálisis enzimática, la estructura celular, el transporte y la respuesta inmunitaria. <br><br><h4>Los cuatro niveles estructurales</h4>La estructura primaria es la secuencia de aminoácidos; la secundaria incluye hélices α y láminas β; la terciaria es la conformación tridimensional completa; y la cuaternaria se forma al ensamblarse varias subunidades polipeptídicas.",
    bio_edu_rep_title: "Replicación del ADN (semiconservativa)",
    bio_edu_rep_content: "La replicación del ADN ocurre antes de la división celular. La helicasa separa las dos cadenas, la primasa de ARN proporciona el punto de inicio, la ADN polimerasa sintetiza la nueva cadena en dirección 5' a 3' y la ligasa une los fragmentos de Okazaki. Cada molécula hija contiene una cadena antigua y una nueva.",
    bio_edu_synth_title: "Dogma central y síntesis de proteínas",
    bio_edu_synth_content: "La información genética suele fluir de <b>ADN ➔ ARN ➔ proteína</b>. En la transcripción se sintetiza ARNm a partir de una cadena molde de ADN; en la traducción, el ribosoma lee los codones del ARNm y une los aminoácidos en orden para formar una cadena polipeptídica.",
    bio_edu_cell_title: "Biología celular y funciones de los orgánulos",
    bio_edu_cell_content: "La célula es la unidad estructural y funcional básica de los seres vivos. La membrana celular regula el paso de sustancias, el núcleo almacena el ADN, las mitocondrias producen ATP y el retículo endoplasmático y el aparato de Golgi procesan y transportan proteínas. Los lisosomas realizan la digestión intracelular.",

