    seti_transit: "Observation du transit : la lumière stellaire a diminué de %{drop}.",
    seti_report_von_title: "Colonisation de Von Neumann",
    seti_report_von_summary: "<strong>De quoi s'agit-il ?</strong> Une expérience de pensée sur une civilisation qui se répand d'étoile en étoile grâce à des vaisseaux autoréplicateurs.",
    seti_report_von_explanation: "<strong>Que voyez-vous ?</strong> Les points bleus représentent les systèmes stellaires atteints et les anneaux l'arrivée d'une sonde dans un nouveau système. Une vitesse de sonde plus élevée facilite l'accès aux systèmes lointains, mais chaque nouveau système nécessite 50 ans pour produire une sonde.",
    seti_report_von_note: "<strong>Comment lire le résultat ?</strong> Il ne s'agit pas du véritable temps de colonisation de la Voie lactée. Le modèle montre l'effet des années-lumière, de la vitesse et du temps de production.",
    seti_report_dark_title: "Forêt sombre",
    seti_report_dark_summary: "<strong>De quoi s'agit-il ?</strong> Un scénario de théorie des jeux qui étudie si une civilisation devient une cible en se rendant visible par ses émissions.",
    seti_report_dark_explanation: "<strong>Que voyez-vous ?</strong> L'onde jaune est un signal radio se propageant à la vitesse de la lumière. La ligne rose représente une attaque plus lente. Une civilisation peut répondre si elle détecte le signal avec une puissance suffisante.",
    seti_report_dark_note: "<strong>Comment lire le résultat ?</strong> La probabilité de réponse n'est pas une observation. La puissance de l'émetteur, la largeur de bande et la température du récepteur déterminent si le signal est détectable ; le réglage de réponse détermine la suite des événements.",
    seti_report_dyson_title: "Essaim de Dyson et courbe de lumière",
    seti_report_dyson_summary: "<strong>De quoi s'agit-il ?</strong> Une visualisation de l'apparence lointaine d'une civilisation qui collecte l'énergie autour de son étoile.",
    seti_report_dyson_explanation: "<strong>Pourquoi la lumière ne diminue-t-elle que de quelques pour cent ?</strong> Les panneaux ne passent pas tous devant l'étoile en même temps et chacun ne couvre qu'une petite fraction du disque stellaire. Une baisse de quelques points de pourcentage est normale avec ces paramètres.",
    seti_report_dyson_note: "<strong>Pourquoi la valeur IR est-elle si faible ?</strong> Les panneaux ne captent qu'une petite fraction de la lumière totale de l'étoile. Il s'agit d'une estimation normalisée de l'énergie captée, et non d'un véritable spectre infrarouge.",

