    drake_info_r_title: "Taux de formation stellaire (R*)",
    drake_info_r_body: "Le nombre d'étoiles qui se forment chaque année dans notre galaxie. Ce facteur est très bien contraint par les observations modernes. Environ <strong>2 étoiles/an</strong> ⭐",
    drake_info_fp_title: "Fraction d'étoiles avec des planètes (fp)",
    drake_info_fp_body: "La fraction d'étoiles qui possèdent au moins une planète. Selon les données du télescope spatial Kepler, presque toutes les étoiles ont des planètes : environ <strong>100 % (1,0)</strong>.",
