    drake_info_fl_title: "Fraction avec de la vie (fl)",
    drake_info_fl_body: "La probabilité que la vie apparaisse sur une planète habitable. Très incertaine : les estimations pessimistes suggèrent <strong>0,1 %</strong>, les optimistes jusqu'à <strong>100 %</strong>.",
    drake_info_fi_title: "Fraction développant l'intelligence (fi)",
    drake_info_fi_body: "La probabilité qu'une vie intelligente et consciente apparaisse une fois la vie émergée. Très spéculative, généralement estimée entre <strong>1 % et 50 %</strong>.",
    drake_info_fc_title: "Fraction avec une technologie (fc)",
    drake_info_fc_body: "La probabilité qu'une espèce intelligente développe une technologie capable de communiquer par radio. Estimée entre <strong>1 % et 50 %</strong>.",
    drake_info_l_title: "Durée de vie technologique (L)",
    drake_info_l_body: "La durée pendant laquelle une civilisation reste active et émet des signaux radio détectables. C'est le facteur le plus spéculatif. Estimée entre <strong>100 ans et 10 millions d'années</strong>. ⏳",
    drake_info_earth_title: "Référence terrestre",
    drake_info_earth_body: "<strong>La Terre</strong> existe depuis 4,5 milliards d'années, la vie depuis 3,8 milliards d'années, Homo sapiens depuis environ 300 000 ans et la <strong>civilisation radio depuis environ 100 ans.</strong> Si la Terre est représentative, L pourrait être d'environ 100 à 500 000 ans. Avec cette hypothèse et le scénario modéré de l'équation de Drake, on obtient <strong>environ 2 000 civilisations</strong>.",
    drake_info_seti_title: "SETI et le trou d'eau cosmique",
    drake_info_seti_body: "SETI (recherche d'intelligence extraterrestre) recherche des signaux artificiels dans la bande de 1,420 à 1,666 GHz. Cette bande est appelée « trou d'eau » car elle se situe entre les raies de l'hydrogène (1,420 GHz) et de l'hydroxyle (1,666 GHz), H + OH = H₂O. Cette région calme est la fenêtre la plus naturelle pour que des civilisations intelligentes se recherchent.",

