    ig_fact_current_title: "Situation actuelle (K ≈ 0,73)",
    ig_fact_current: "L'humanité se trouve actuellement au stade de type 0. Nous tirons l'essentiel de notre énergie des combustibles fossiles et de la fission nucléaire. Il nous faudra peut-être encore 100 à 200 ans pour atteindre le type 1.",
    ig_fact_type0_title: "Civilisation de type 0",
