    mc_reset: "RÉINITIALISER",
    mc_edu_toggle: "Menu et explications",
    mc_edu_html: "<b>Analyse statistique et écart type</b><br>La désintégration radioactive est un processus stochastique (aléatoire) en temps continu.<br><span class=\"edu-formula\">λ = (ln 2) / t½</span><br><span class=\"highlight-orange\">🔬 Détermination de la demi-vie et intervalle de confiance</span><br>Ce laboratoire ne calcule pas seulement une moyenne lorsque vous lancez plusieurs expériences. Il <b>mesure indépendamment la demi-vie de chaque</b> simulation de 10, 100 ou 1000 expériences.<br><br>Il calcule ensuite l'écart type (<b>σ</b>) et l'intervalle de confiance à 95 %. En augmentant le nombre d'expériences (N), vous pouvez observer la diminution spectaculaire de l'erreur standard et de la marge d'erreur, ce qui illustre la précision des données scientifiques.",
