    // --- SIMULATION PAGE: ADVANCED QUANTUM INTERFERENCE ---
    qs_title: "Simulation avancée de l'interférence quantique",
    qs_heading: "Simulation quantique avancée",
    qs_lbl_particle_type: "Type de particule :",
    qs_opt_photon: "Lumière (photon) - Sans masse",
    qs_opt_electron: "Matière (électron) - Avec masse",
    qs_lbl_view_mode: "Mode d'affichage :",
    qs_opt_wave: "Mode onde classique",
    qs_opt_quantum: "Mode particule quantique",
    qs_lbl_exp_mode: "Mode d'expérience :",
    qs_opt_double: "Double fente (figure d'interférence)",
    qs_opt_single: "Fente unique (diffraction uniquement)",
    qs_opt_detector: "Double fente + détecteur (effet de l'observateur)",
    qs_lbl_speed_mode: "Vitesse d'émission :",
    qs_opt_fast: "Rapide (émission continue)",
    qs_opt_slow: "Lente (émission intermittente)",
    qs_opt_single_particle: "Un seul (attendre l'impact)",
    qs_lbl_lambda: "Longueur d'onde (λ) :",
    qs_lbl_energy: "Énergie de l'électron (E) :",
    qs_lbl_distance: "Distance entre les fentes (d) :",
    qs_lbl_width: "Largeur de la fente (a) :",
    qs_btn_reset: "Réinitialiser l'écran et le graphique",
    qs_lbl_hits: "Particules atteignant le détecteur :",
    qs_info_title: " Explications scientifiques",
    qs_info_duality_title: "Dualité onde-particule",
    qs_info_duality_desc: "En physique classique, la lumière se comporte comme une onde. Cependant, en <span class=\"highlight-text\">mode quantique</span>, même lorsque les particules (photons ou électrons) sont envoyées une par une, une figure d'interférence identique au modèle ondulatoire apparaît progressivement à l'écran. Les amplitudes de probabilité de la particule traversent les deux fentes et produisent des interférences.",
    qs_info_observer_title: "Effet de l'observateur (effondrement de la fonction d'onde)",
    qs_info_observer_desc: "Lorsque vous ajoutez un <span class=\"danger-text\">détecteur</span> pour mesurer par quelle fente passe la particule, le comportement quantique s'effondre. La mesure provoque l'effondrement de la fonction d'onde ; les particules se comportent comme des boules de billard classiques et la figure d'interférence disparaît, remplacée par deux bandes distinctes.",
    qs_info_physics_title: "Moteur physique (unités SI)",
