Object.keys(scientificTextCorrections).forEach(lang => {
    if (translations[lang]) Object.assign(translations[lang], scientificTextCorrections[lang]);
});

Object.keys(translations)
    .filter(lang => !scientificTextCorrections[lang])
    .forEach(lang => Object.assign(translations[lang], scientificTextCorrections.en));

let currentLang = localStorage.getItem('cosmos_lang') || 'tr';
currentMode = null; 
function t(key) {
    if (translations[currentLang] && translations[currentLang][key]) {
        return translations[currentLang][key];
    }
    return key;
}

function updatePageLanguage() {
    document.documentElement.lang = currentLang;

    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (translations[currentLang] && translations[currentLang][key]) {
            if (element.tagName === 'TITLE') {
                document.title = translations[currentLang][key];
            } else {
                element.innerHTML = translations[currentLang][key];
            }
        }
    });

    document.querySelectorAll('[data-i18n-aria-label]').forEach(element => {
        const key = element.getAttribute('data-i18n-aria-label');
        if (translations[currentLang] && translations[currentLang][key]) {
            element.setAttribute('aria-label', translations[currentLang][key]);
        }
    });

    document.querySelectorAll('.lang-btn').forEach(btn => {
        if (btn.getAttribute('data-lang') === currentLang) {
            btn.classList.add('active');
        } else {
            btn.classList.remove('active');
        }
    });

    if (window.onLanguageChange && typeof window.onLanguageChange === 'function') {
        window.onLanguageChange();
    }
}

function setLanguage(lang) {
    if (translations[lang]) {
        currentLang = lang;
        localStorage.setItem('cosmos_lang', lang);
        updatePageLanguage();

        // Drake sayfası açıksa, değerleri dinamik olarak güncelle
        if (typeof updateValues === 'function') {
            updateValues();
        }
    }
}

// Sayfaya yüklendiğinde çalıştır
document.addEventListener('DOMContentLoaded', updatePageLanguage);


function setMode(mode) {
    if (!mode) return;

    currentMode = mode;
    
    const buttons = document.querySelectorAll('#menu-panel .btn, [data-mode-btn]');
    buttons.forEach(btn => btn.classList.remove('active'));

    const activeBtn = document.getElementById('btn-' + mode) ||
        document.querySelector(`[data-mode="${mode}"]`);
    if (activeBtn) {
        activeBtn.classList.add('active');
    }

    if (typeof updatePanelContent === 'function') {
        updatePanelContent();
    }

    if (typeof renderer !== 'undefined' && typeof camera !== 'undefined' && typeof scene !== 'undefined' && renderer && camera && scene) {
        renderer.render(scene, camera);
    }
}